const DATA = [

/* ============================ 1. АПОЛОГЕТИКА ============================ */
{
 id:"apologetika", title:"Апологетика",
 sub:"Разумность веры и доводы о бытии Божием",
 qa:[
  {q:"Что такое апологетика?",
   a:`<p>Апологетика — раздел богословия, который обосновывает разумность христианской веры, отвечает на возражения против неё и защищает её от искажений. Само слово происходит от греческого «апология» — «защита», «оправдание на суде».</p>
   <p>Апологетика не заменяет веру доказательством и не «принуждает» к ней: вера остаётся свободным доверием сердца Богу. Но она показывает, что вера не противоречит разуму и опирается на действительные основания — устройство мира, исторические события, свидетельство совести и опыт Церкви.</p>
   <p>Её задача выражена словами апостола Петра: быть всегда готовыми «всякому, требующему у вас отчёта в вашем уповании, дать ответ с кротостью и благоговением» ([[1 Пет 3:15]]). Уже в первые века христианские писатели-апологеты (Иустин Философ, Афинагор, Тертуллиан) защищали веру перед языческим обществом.</p>`, s:SRC.pis+" · "+SRC.ist},
  {q:"Можно ли строго доказать существование Бога?",
   a:`<p>Строгого доказательства, принуждающего разум так же, как теорема геометрии, нет — и его отсутствие не случайно: будь оно, вера перестала бы быть свободным выбором. Однако это не значит, что вера безосновательна.</p>
   <p>Ричард Суинберн различает три типа доводов. <em>Дедуктивный</em> — где из посылок с необходимостью следует вывод. <em>«П-индуктивный»</em> (правильный индуктивный) — где посылки делают вывод <em>вероятным</em>, более вероятным, чем неверие. И <em>«C-индуктивный»</em> — где посылки лишь <em>повышают</em> вероятность вывода, не доказывая его окончательно.</p>
   <p>По Суинберну, отдельные доводы о бытии Божием — именно C-индуктивные: каждый сам по себе только повышает вероятность теизма. Но взятые вместе, в совокупности, они образуют сильный П-индуктивный аргумент, делающий существование Бога более вероятным, чем его отсутствие.</p>`, s:SRC.sw},
  {q:"Что такое естественная теология?",
   a:`<p>Естественная теология — это познание Бога, доступное человеческому разуму из наблюдения над миром и над собой, без опоры на прямое сверхъестественное откровение. Она восходит от фактов (существование вселенной, её порядок, сознание, нравственность) к их наилучшему объяснению.</p>
   <p>Писание признаёт такой путь: «невидимое Его, вечная сила Его и Божество, от создания мира через рассматривание творений видимы» ([[Рим 1:20]]), и «небеса проповедуют славу Божию» ([[Пс 18:2]]). Суинберн развивает именно естественную теологию, показывая, что гипотеза Бога лучше всего объясняет мир как целое.</p>`, s:SRC.sw},
  {q:"Какого Бога имеет в виду теизм у Суинберна?",
   a:`<p>Под теизмом Суинберн понимает утверждение, что существует личность без тела — то есть Дух, — которая вечна, совершенно свободна, всемогуща, всеведуща, всеблага и является творцом всего существующего.</p>
   <p>Важно, что это <em>одна</em> личность с бесконечными свойствами. Именно единство и бесконечность делают гипотезу теизма простой, а простота, по Суинберну, — главный признак вероятной истинности объяснения. Такое понимание Бога совпадает с верой Церкви в единого всесовершенного Бога-Творца.</p>`, s:SRC.sw},
  {q:"Почему простота гипотезы так важна?",
   a:`<p>При объяснении любых фактов наука и здравый смысл предпочитают простейшую гипотезу, которая объясняет данные. Из двух теорий, одинаково согласных с наблюдениями, вероятнее та, что проще — постулирует меньше сущностей и более единообразна.</p>
   <p>Суинберн показывает, что теизм отвечает этому критерию как никакая другая гипотеза: он объясняет существование и устройство всего мира действием единого существа. Бесконечное свойство (всемогущество) проще, чем произвольная конечная величина силы, потому что не требует объяснять, «почему именно столько».</p>
   <p>Поэтому у теизма высокая «предварительная вероятность» — он вероятен ещё до рассмотрения конкретных данных, просто как самое экономное фундаментальное объяснение.</p>`, s:SRC.sw},
  {q:"В чём суть космологического аргумента?",
   a:`<p>Космологический аргумент идёт от самого факта, что вселенная существует, к её Причине. Мир не объясняет себя сам: он мог бы и не существовать вовсе, и наука, описывая, как устроен мир, не отвечает на вопрос, почему вообще есть нечто, а не ничто.</p>
   <p>Суинберн формулирует его как индуктивный: существование сложной физической вселенной — то, чего мы не ожидали бы «просто так», но чего разумно ожидать, если её свободно создал Бог. Значит, факт её бытия повышает вероятность теизма.</p>
   <p>Это перекликается с исповеданием веры: «В начале сотворил Бог небо и землю» ([[Быт 1:1]]); «Им создано всё» ([[Кол 1:16]]). Бог — не одна из причин внутри мира, а Причина самого бытия мира.</p>`, s:SRC.sw},
  {q:"В чём суть телеологического аргумента?",
   a:`<p>Телеологический аргумент (от греч. «телос» — цель) идёт от порядка и целесообразности в мире к разумному Устроителю. Суинберн особо выделяет «временну́ю упорядоченность» — то, что вся вселенная во всякое время и в каждой точке действует по одним и тем же простым, единообразным законам.</p>
   <p>Такое всеохватное единообразие само требует объяснения. Оно естественно, если мир создан единым разумным Существом, желающим упорядоченного космоса, и крайне маловероятно как «слепая» случайность. Пророк говорит: «Небеса проповедуют славу Божию, и о делах рук Его вещает твердь» ([[Пс 18:2]]).</p>`, s:SRC.sw},
  {q:"Что такое аргумент от «тонкой настройки» вселенной?",
   a:`<p>Современная физика показывает, что фундаментальные постоянные и начальные условия вселенной «настроены» в чрезвычайно узких пределах: даже ничтожное их изменение сделало бы невозможным появление звёзд, химии и жизни.</p>
   <p>Суинберн отмечает: без Бога такая точная настройка мира на возникновение телесных, разумных существ была бы a priori крайне невероятной. Но для благого Творца, желающего разумных существ, способных познавать и делать выбор, она вполне ожидаема. Смысл человеческого тела в том, что оно — средство познания мира и осуществления целей.</p>
   <p>Поэтому «тонкая настройка» — сильный частный случай телеологического довода: она повышает вероятность того, что за миром стоит замысел.</p>`, s:SRC.sw},
  {q:"Как из существования сознания следует довод о Боге?",
   a:`<p>Материя, действующая по физическим законам, сама по себе не порождает с необходимостью сознание — субъективный внутренний опыт, переживание боли, цвета, мысли. Существование сознательных существ — это новый факт, который физика описать, но не объяснить не может.</p>
   <p>Суинберн доказывает: возникновение сознания гораздо вероятнее, если есть Бог, желающий существ, способных мыслить, чувствовать и любить, чем если мир — лишь бесцельная игра частиц. Поэтому сам факт сознания повышает вероятность теизма.</p>`, s:SRC.sw},
  {q:"Что такое нравственный аргумент?",
   a:`<p>Люди сознают объективное различие добра и зла и чувствуют себя <em>обязанными</em> поступать хорошо, даже вопреки выгоде. Из одной материи и эволюционной пользы это чувство долга и объективность нравственного закона вывести трудно.</p>
   <p>Наличие подлинной, а не только условной морали указывает на её Источник — благого Бога, вложившего в человека нравственный закон. Апостол пишет о язычниках, у которых «дело закона написано в сердцах» ([[Рим 2:15]]).</p>`, s:SRC.sw},
  {q:"Что такое аргумент от Промысла?",
   a:`<p>Мир устроен так, что даёт разумным существам широкую возможность познавать законы природы, свободно выбирать и реально влиять на себя, на других и на среду — в том числе заботиться друг о друге. Это устройство особенно ценно для нравственного возрастания.</p>
   <p>Суинберн замечает, что такой мир — не «стерильный рай» и не хаос, а именно поприще ответственного действия — естественно ожидать от благого Бога, дающего Своим созданиям достоинство соучастия в добре. Господь говорит: «Отец Мой доныне делает» ([[Ин 5:17]]).</p>`, s:SRC.sw},
  {q:"Если Бог благ и всемогущ, почему в мире есть зло?",
   a:`<p>Это главное возражение против веры, и Суинберн отвечает на него теодицеей — оправданием благости Бога перед лицом зла. Он различает зло <em>нравственное</em> (причиняемое злой волей) и <em>естественное</em> (болезни, стихии).</p>
   <p>Ключ — в свободе и в высших благах. Многие величайшие блага — мужество, сострадание, самопожертвование, прощение, возрастание в добре — по своей природе возможны лишь там, где есть реальный выбор, трудность и даже страдание. Дать творению подлинную свободу творить добро — значит допустить и возможность зла; без этого мир был бы беднее.</p>
   <p>Поэтому мир, в котором есть свобода и риск зла, может быть лучше мира, где зло невозможно, потому что невозможно и настоящее добро. Апостол свидетельствует: «нынешние временные страдания ничего не стоят в сравнении с той славою, которая откроется в нас» ([[Рим 8:18]]).</p>`, s:SRC.sw},
  {q:"Зачем в мире естественное зло — болезни и катастрофы?",
   a:`<p>Труднее всего объяснить не злодеяния людей, а «естественное» зло — страдание, не зависящее от чьей-то злой воли. Суинберн предлагает несколько соображений.</p>
   <p>Во-первых, естественное зло создаёт саму возможность знания о последствиях и, значит, ответственного выбора: человек учится, что причиняет вред, и получает власть предотвращать его. Во-вторых, оно открывает простор для высших добродетелей — мужества, терпения, сострадания, самоотвержения, которые без реальной беды были бы невозможны.</p>
   <p>Даже в мире животных, чья свобода ограничена, страдание связано с благом заботы: высшие животные наделены родительским инстинктом и способностью беречь потомство. Страдание не самоцель и не благо само по себе, но цена мира, в котором возможно подлинное добро.</p>`, s:SRC.sw},
  {q:"Что такое аргумент от чудес и истории?",
   a:`<p>Если уже есть основания считать, что благой Бог существует и может иногда действовать в мире, то исторические свидетельства о чудесах перестают быть невероятными. Чудо Суинберн понимает как событие, вызванное особым действием Бога и выходящее за рамки естественного хода вещей ради блага и как знамение.</p>
   <p>Центральное для христианства историческое свидетельство — Воскресение Христово, которое апостолы проповедовали как очевидцы и за которое шли на смерть. Такие события, если они подтверждены свидетельством, служат дополнительным и сильным доводом в пользу теизма и истинности христианского откровения.</p>`, s:SRC.sw},
  {q:"Что такое аргумент от религиозного опыта?",
   a:`<p>Это довод от того, что огромному множеству людей в разные эпохи «является» присутствие Бога — в молитве, в переживании священного, в озарении, у немногих в мистическом видении. Суинберн систематизирует такой опыт и придаёт ему доказательную силу.</p>
   <p>Опираясь на «принцип доверия», он утверждает: разумно принимать, что вещи таковы, какими они являются, пока нет особых причин думать иначе. Если так мы относимся к обычному восприятию, то и массовое свидетельство о богоприсутствии следует принимать всерьёз — оно повышает вероятность бытия Божия. Господь обещал: «ищущий находит» ([[Мф 7:8]]).</p>`, s:SRC.sw},
  {q:"Что такое «принцип доверия» (credulity)?",
   a:`<p>Принцип доверия — введённое Суинберном правило рациональности: <em>если субъекту кажется, что нечто существует (и обладает какими-то признаками), то, при отсутствии особых опровергающих оснований, вероятно, оно действительно существует</em>. Точно так же следует доверять и явным воспоминаниям.</p>
   <p>Без этого принципа рухнуло бы всякое познание: мы вынуждены доверять восприятию и памяти, иначе не могли бы знать ничего. Суинберн распространяет его и на религиозный опыт, но с оговорками: доверие ослабевает, если известны искажающие факторы (например, воздействие наркотиков) или если есть сильные независимые основания сомневаться.</p>`, s:SRC.sw},
  {q:"Какие виды религиозного опыта различает Суинберн?",
   a:`<p>Суинберн выделяет пять видов. Два первых — <em>общедоступные</em>: когда человек воспринимает Бога через обычный публичный объект (например, видя красоту звёздного неба) или через необычное общественное событие. Третий — восприятие Бога через частные, но описуемые обычными словами явления (как ангел, говорящий человеку).</p>
   <p>Четвёртый — частный опыт, который субъект не может описать обычным языком (мистический опыт). Пятый — опыт, при котором нет вообще никакого чувственного восприятия, но человек непосредственно сознаёт присутствие Бога. Все они, по принципу доверия, служат свидетельством.</p>`, s:SRC.sw},
  {q:"Как все доводы соединяются вместе?",
   a:`<p>Суинберн подчёркивает, что ни один аргумент не решает вопрос сам по себе — сила в их совокупности. Он оценивает их по «соотношению вероятностей», складывая простоту теизма (высокую предварительную вероятность) и вклад каждого свидетельства.</p>
   <p>Существование упорядоченной вселенной, её тонкая настройка, сознание, нравственность, промыслительное устройство, чудеса истории и религиозный опыт — каждый факт по отдельности лишь повышает вероятность. Но вместе, по его итоговой оценке, они делают существование Бога более вероятным, чем его отсутствие.</p>`, s:SRC.sw},
  {q:"Противоречат ли наука и вера?",
   a:`<p>Нет. Наука и вера отвечают на разные вопросы. Наука описывает, <em>как</em> устроен мир и по каким законам он действует; вера отвечает, <em>почему</em> вообще есть упорядоченный мир и эти законы, и в чём его смысл и цель.</p>
   <p>Даже полное научное объяснение процессов не отменяет вопроса о причине самого бытия и порядка. Поэтому объяснение «через законы природы» и объяснение «через замысел Бога» не конкурируют, а находятся на разных уровнях: Бог — Причина того, что вообще есть законы. Многие крупные учёные были людьми глубокой веры.</p>`, s:SRC.sw},
  {q:"Не объясняет ли теория эволюции сложность мира без Бога?",
   a:`<p>Эволюция может объяснять, как из простых форм жизни развились сложные, но она предполагает уже готовыми и жизнь, и точно настроенные законы природы, делающие развитие возможным. Откуда сами эти законы и условия — вопрос, на который эволюция не отвечает.</p>
   <p>Суинберн указывает: механизм естественного отбора сам есть часть того упорядоченного мира, который нуждается в объяснении. Верующий может принимать научную картину развития жизни, видя в ней <em>способ</em>, которым Бог осуществляет Свой замысел, а не замену Творцу.</p>`, s:SRC.sw},
  {q:"Разве множество разных религий не опровергает веру?",
   a:`<p>Разнообразие религий показывает, что человек по природе религиозен — ищет Бога, — но само по себе не доказывает, что все они ложны, как разнообразие научных мнений не отменяет истины. Различие свидетельств не уничтожает их, а требует различения.</p>
   <p>Христианство утверждает, что во Христе Бог открыл Себя полнее всего, и что отблески истины могли быть и вне его. Апостол говорит, что Бог «не переставал свидетельствовать о Себе благодеяниями» всем народам ([[Деян 14:17]]), а полнота истины дана во Христе.</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Разве вера — это не просто субъективное чувство?",
   a:`<p>Христианская вера включает доверие сердца, но не сводится к настроению или эмоции. Она опирается на исторические события — жизнь, смерть и Воскресение Христа, засвидетельствованные очевидцами, — на разумные доводы естественной теологии и на опыт многих поколений Церкви.</p>
   <p>Библейское слово «вера» (греч. «пистис») ближе к «верности» и «доверию», чем к «мнению без оснований». Это разумное доверие Тому, Кого есть основания считать благим и истинным, а не слепой прыжок в темноту. «Вера же есть осуществление ожидаемого и уверенность в невидимом» ([[Евр 11:1]]).</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Почему Бог не сделает Своё существование очевидным для всех?",
   a:`<p>Слишком явное, принудительное знание о Боге лишило бы человека свободы в главном — в свободном обращении к Богу любовью. Вера предполагает доверие там, где есть место и сомнению; иначе не было бы ни заслуги, ни личного выбора.</p>
   <p>Бог оставляет достаточно свидетельств для ищущего сердца, но не «подавляет» волю очевидностью. Господь ублажает «не видевших и уверовавших» ([[Ин 20:29]]), а пророк говорит о «Боге сокровенном» ([[Ис 45:15]]), Который открывается смиренным и взыскующим Его.</p>`, s:SRC.sw+" · "+SRC.pis}
 ]
},

/* ============================ 2. БИБЛИОЛОГИЯ ============================ */
{
 id:"bibliologiya", title:"Учение о Священном Писании",
 sub:"Библиология: канон, богодухновенность, толкование",
 qa:[
  {q:"Что такое Священное Писание?",
   a:`<p>Священное Писание, или Библия (греч. «книги»), — это собрание книг, написанных святыми людьми по вдохновению Святого Духа и признанных Церковью богооткровенными. В них Бог возвещает людям Себя, Свою волю и путь спасения.</p>
   <p>Писание не «упало с неба» готовым, а слагалось в течение веков внутри народа Божия и Церкви. Оно — не единственный, но важнейший письменный источник вероучения и составляет вместе со Священным Преданием единое слово Божие. «Всё Писание богодухновенно и полезно для научения, для обличения, для исправления, для наставления в праведности» ([[2 Тим 3:16]]).</p>`, s:SRC.dog},
  {q:"Что такое богодухновенность?",
   a:`<p>Богодухновенность — это особое действие Святого Духа, под которым священные писатели излагали истину Божию верно и без заблуждения в том, что касается спасения. При этом Дух не подавлял их личности: каждый писал своим языком, стилем и в своих обстоятельствах.</p>
   <p>Поэтому Писание — вполне слово Божие и вместе слово человеческое, подобно тому как Христос — истинный Бог и истинный человек. «Никогда пророчество не было произносимо по воле человеческой, но изрекали его святые Божии человеки, будучи движимы Духом Святым» ([[2 Пет 1:21]]).</p>`, s:SRC.dog},
  {q:"Из скольких частей состоит Библия?",
   a:`<p>Библия делится на две большие части — Ветхий Завет и Новый Завет. Слово «завет» означает союз Бога с людьми. Ветхий Завет — книги, написанные до пришествия Христа, о союзе Бога с народом Израиля и об ожидании Спасителя. Новый Завет — книги о пришедшем Христе и о Церкви.</p>
   <p>Оба Завета говорят об одном деле спасения: Ветхий приготовляет и прообразует, Новый исполняет. Блаженный Августин выразил это так: Новый Завет в Ветхом скрывается, а Ветхий в Новом открывается. Христос Сам свидетельствовал, что Моисей и пророки писали о Нём ([[Лк 24:27]]).</p>`, s:SRC.dog},
  {q:"Что такое канон Писания?",
   a:`<p>Канон (греч. «правило», «мерило») — это список книг, которые Церковь признала подлинно богодухновенными и включила в состав Писания, отличив их от книг лишь полезных или подложных.</p>
   <p>Новый Завет содержит 27 книг: четыре Евангелия, Деяния апостолов, семь соборных посланий, четырнадцать посланий апостола Павла и Апокалипсис. Их состав установился в Церкви к IV веку. Ветхозаветный канон Церковь приняла в его греческом (Септуагинтовом) объёме, более широком, чем позднейший еврейский.</p>`, s:SRC.pis+" · "+SRC.dog},
  {q:"Что такое Евангелие?",
   a:`<p>Слово «Евангелие» значит «благая весть» — весть о спасении, дарованном во Христе. В узком смысле так называют четыре книги, повествующие о жизни, учении, смерти и Воскресении Господа: от Матфея, Марка, Луки и Иоанна.</p>
   <p>Первые три Евангелия называют синоптическими (от греч. «общий взгляд»), потому что они близки по содержанию и порядку. Евангелие от Иоанна отличается более созерцательным, богословским изложением. Все четыре Церковь принимает как единое четвероевангелие — одно благовестие в четырёх изложениях.</p>`, s:SRC.pis},
  {q:"Что такое Пятикнижие?",
   a:`<p>Пятикнижие — первые пять книг Библии: Бытие, Исход, Левит, Числа и Второзаконие, по преданию написанные пророком Моисеем. По-еврейски они называются «Тора» — «Закон», «Наставление».</p>
   <p>Бытие повествует о сотворении мира и о патриархах, Исход — об избавлении народа из Египта и даровании закона на Синае, остальные — о богослужебном законе и странствии к обетованной земле. Пятикнижие — основание всего Ветхого Завета. Сам Господь ссылается на слова, сказанные Богом Моисею ([[Исх 3:6]]).</p>`, s:SRC.pis},
  {q:"Кто такие пророки?",
   a:`<p>Пророки — избранные Богом мужи, которых Дух Святой призывал возвещать народу волю Божию: обличать грех, звать к покаянию и предсказывать будущее, прежде всего — пришествие Мессии. Пророчество — не столько предсказание, сколько «изречение от лица Божия».</p>
   <p>Различают великих пророков (Исаия, Иеремия, Иезекииль, Даниил) и двенадцать малых — по объёму их книг. Через пророка Иеремию Бог обещал «новый завет» ([[Иер 31:31]]), а Исаия за века предсказал страдания Мессии ([[Ис 53:5]]). Их предсказания, исполнившиеся во Христе, — одно из свидетельств истины веры.</p>`, s:SRC.pis},
  {q:"Что такое Псалтирь?",
   a:`<p>Псалтирь — ветхозаветная книга из 150 псалмов, священных песней, большинство которых надписаны именем царя Давида. Это молитвенник Церкви: в псалмах есть покаяние, славословие, благодарение, прошение, пророчество о Христе.</p>
   <p>Псалтирь чаще других книг употребляется в богослужении и в домашней молитве. Многие псалмы прямо указывают на Христа: о Его страдании («Боже Мой, Боже Мой! для чего Ты Меня оставил?» — [[Пс 21:2]]) и о Его царстве ([[Пс 109:1]]).</p>`, s:SRC.pis},
  {q:"Что такое Септуагинта?",
   a:`<p>Септуагинта — древнейший перевод Ветхого Завета с еврейского на греческий язык, сделанный в Александрии в III–II вв. до Р. Х. Название (лат. «семьдесят») связано с преданием о семидесяти (точнее, семидесяти двух) переводчиках.</p>
   <p>Именно этим переводом пользовались апостолы и грекоязычная Церковь; большинство ветхозаветных цитат в Новом Завете приведены по нему. Церковь принимает Септуагинту как авторитетный текст Ветхого Завета, и её объём лёг в основу православного канона.</p>`, s:SRC.pis},
  {q:"Как правильно толковать Писание?",
   a:`<p>Писание должно толковаться в согласии с верой и Преданием Церкви, а не по частному произволу, ибо «никакого пророчества в Писании нельзя разрешить самому собою» ([[2 Пет 1:20]]). Церковь, в которой Писание родилось, и есть его верная истолковательница.</p>
   <p>Правила отеческого толкования таковы: тёмные места изъясняются ясными; отдельное место понимается в согласии со всем Писанием; всё читается в свете Христа, к Которому ведёт весь текст. Толкование не должно противоречить согласному учению отцов и решениям соборов.</p>`, s:SRC.dog},
  {q:"Есть ли в Писании разные смыслы?",
   a:`<p>Да. Отцы различали прежде всего <em>буквальный</em> (исторический) смысл — то, о чём прямо повествует текст, — и <em>духовный</em> смысл, который может быть прообразовательным (когда событие указывает на новозаветную реальность), нравственным и таинственным.</p>
   <p>Так, апостол Павел видит в переходе Израиля через море прообраз крещения ([[1 Кор 10:2]]), а в медном змии, вознесённом Моисеем, Сам Господь усматривает образ Своего распятия ([[Ин 3:14]]). Духовное толкование не отменяет буквального, а надстраивается над ним.</p>`, s:SRC.dog},
  {q:"Не противоречит ли Библия сама себе?",
   a:`<p>Мнимые противоречия обычно снимаются, если учитывать жанр, цель и обстоятельства книги. Евангелисты, например, описывают события с разных сторон и с разной подробностью — как несколько свидетелей одного происшествия, — и это скорее подтверждает подлинность, чем опровергает.</p>
   <p>Писание не есть учебник естествознания и говорит о спасении языком, доступным своему времени. В главном — в вести о Боге и спасении — оно едино и согласно, ибо имеет единого Автора — Духа Святого.</p>`, s:SRC.dog},
  {q:"Достаточно ли одного Писания без Церкви?",
   a:`<p>Писание рождено внутри Церкви, ею собрано в канон и ею же верно истолковывается; оно и Предание неразделимы, как две стороны единого слова Божия. Отделённое от Церкви, Писание становится предметом произвольных и противоречивых толкований — что и показала история множества разделений.</p>
   <p>Апостол велит держаться «преданий, которым вы научены или словом, или посланием нашим» ([[2 Фес 2:15]]), а саму Церковь называет «столпом и утверждением истины» ([[1 Тим 3:15]]). Поэтому Писание читается в Церкви и по вере Церкви.</p>`, s:SRC.dog}
 ]
},

/* ==================== 3. УЧЕНИЕ О БОГЕ (БОГОПОЗНАНИЕ) ==================== */
{
 id:"o-boge", title:"Учение о Боге",
 sub:"Богопознание, существо и свойства Божии",
 qa:[
  {q:"Кто есть Бог?",
   a:`<p>Бог есть вечный, всесовершенный и всеблаженный Дух, Творец и Промыслитель мира, единый по существу и троичный в Лицах — Отец, Сын и Святой Дух. Он — источник и полнота бытия, блага, жизни и любви, не имеющий ни начала, ни причины Своего бытия.</p>
   <p>На вопрос Моисея об имени Бог ответил: «Я есмь Сущий» ([[Исх 3:14]]) — то есть Тот, Кто существует Сам по Себе и даёт бытие всему. В отличие от идолов и стихий, Бог не часть мира, а его Первопричина. «Бог есть любовь» ([[1 Ин 4:8]]) — этим Новый Завет раскрывает самое сокровенное о Нём.</p>`, s:SRC.dog},
  {q:"Можно ли постичь Бога разумом до конца?",
   a:`<p>Нет. Существо Божие непостижимо и превосходит всякое тварное разумение: «Бога не видел никто никогда» ([[Ин 1:18]]), Он «обитает в неприступном свете» ([[1 Тим 6:16]]). Постигнуть Бога вполне значило бы стать больше Бога, что невозможно.</p>
   <p>Поэтому отцы различали <em>апофатическое</em> богословие (о Боге говорят, что́ Он <em>не есть</em>: не ограничен, не изменяем, не сложен) и <em>катафатическое</em> (что́ можно утверждать по Его действиям: благ, премудр). Мы познаём Бога не по недоступному существу, а по Его действиям (энергиям) и свойствам, открытым в творении и в Откровении.</p>`, s:SRC.dog},
  {q:"Как человек познаёт Бога?",
   a:`<p>Двумя путями, которые дополняют друг друга. <em>Естественное</em> откровение — свидетельство о Творце в устройстве и красоте мира и в голосе совести: «невидимое Его… через рассматривание творений видимо» ([[Рим 1:20]]). Оно доступно всем народам, но даёт лишь общее знание о бытии и премудрости Творца.</p>
   <p><em>Сверхъестественное</em> откровение — то, что Сам Бог возвестил через пророков и, наконец, через воплотившегося Сына: «многократно и многообразно говоривший издревле отцам в пророках, в последние дни сии говорил нам в Сыне» ([[Евр 1:1]]). Полнота богопознания — во Христе и в жизни Церкви.</p>`, s:SRC.dog},
  {q:"Что такое свойства Божии?",
   a:`<p>Свойства — это то, что открывает нам совершенства Божественного существа, поскольку оно доступно нашему разумению. Их обычно делят на две группы: свойства, показывающие независимость Бога от условий тварного бытия (самобытность, вечность, неизменяемость, вездесущие), и свойства Его духовной жизни как Ума и Воли (всеведение, премудрость, всемогущество, святость, правда, благость).</p>
   <p>При этом важно помнить: Бог прост и не состоит из частей или свойств. Свойства не «складываются» в Боге, как качества в вещи; каждое есть Сам Бог, рассматриваемый с определённой стороны. Бог не «имеет» благость — Он <em>есть</em> Благость.</p>`, s:SRC.dog},
  {q:"Что значит, что Бог — Дух?",
   a:`<p>Это значит, что Бог невеществен, невидим, бестелесен и прост. Сам Господь сказал: «Бог есть дух, и поклоняющиеся Ему должны поклоняться в духе и истине» ([[Ин 4:24]]). Писание называет Его «Богом невидимым» ([[Кол 1:15]]), «нетленным Царём веков» ([[1 Тим 1:17]]).</p>
   <p>Телесные образы Библии — «рука», «око», «гнев» Божий — не следует понимать буквально; это снисхождение к нашему языку (антропоморфизмы), выражающее действия и отношения Бога понятным нам образом. Как Дух, Бог не ограничен ни местом, ни формой.</p>`, s:SRC.dog},
  {q:"Что значит вечность Божия?",
   a:`<p>Вечность означает, что Бог не имеет ни начала, ни конца и вообще не подчинён времени. Время сотворено вместе с миром, а Бог пребывает выше него: «прежде нежели родились горы… от века и до века Ты — Бог» ([[Пс 89:3]]).</p>
   <p>Для Бога нет «прошлого» и «будущего» в нашем смысле последовательности — Он всё содержит в едином присносущном «ныне». Поэтому Он именует Себя: «Я есмь Альфа и Омега, начало и конец… Который есть и был и грядёт» ([[Откр 1:8]]).</p>`, s:SRC.dog},
  {q:"Что значит неизменяемость Божия?",
   a:`<p>Бог всесовершен, а значит, не может изменяться: улучшение предполагало бы прежнее несовершенство, ухудшение — утрату совершенства. И то и другое несовместимо с полнотой Божества. «Я — Господь, Я не изменяюсь» ([[Мал 3:6]]); у Него «нет изменения и ни тени перемены» ([[Иак 1:17]]).</p>
   <p>Когда Писание говорит, что Бог «раскаялся» или «умилостивился», это описывает не перемену в Боге, а перемену в отношениях с людьми, происходящую от перемены самих людей. Неизменен не только Бог, но и Его благой замысел о мире.</p>`, s:SRC.dog},
  {q:"Что такое вездесущие Божие?",
   a:`<p>Вездесущие означает, что Бог не ограничен пространством и присутствует везде — всем существом, а не частями. «Куда пойду от Духа Твоего, и от лица Твоего куда убегу?» ([[Пс 138:7]]); Он наполняет небо и землю ([[Иер 23:24]]).</p>
   <p>При этом Бог присутствует в мире не сливаясь с ним (это отличает веру от пантеизма): мир в Боге, но Бог больше мира. Особым образом Бог являет Своё присутствие благодатью — в храме, в таинствах, в сердце святых.</p>`, s:SRC.dog},
  {q:"Что такое всеведение Божие?",
   a:`<p>Всеведение — совершенное знание Богом всего: прошедшего, настоящего и будущего, действительного и возможного, явного и самого сокровенного, вплоть до помышлений сердца. «Всё обнажено и открыто перед очами Его» ([[Евр 4:13]]); «Господь испытует все сердца» ([[1 Пар 28:9]]).</p>
   <p>Знание Божие не приобретается постепенно и не есть догадка: Бог знает всё сразу и совершенно. Это ведение — основание и правды Его (Он судит по истине), и Промысла (Он всё предусматривает ко благу).</p>`, s:SRC.dog},
  {q:"Что такое всемогущество Божие?",
   a:`<p>Всемогущество означает, что Бог может совершить всё, что хочет и что согласно с Его совершенством: «Богу всё возможно» ([[Мф 19:26]]); «Он сказал — и сделалось» ([[Пс 32:9]]).</p>
   <p>Всемогущество не есть способность к бессмыслице или ко злу. Бог не может лгать ([[Тит 1:2]]), не может отречься Себя ([[2 Тим 2:13]]), не может сотворить противоречие — но это не «немощь», а совершенство: зло и ложь суть недостаток бытия, а не проявление силы. Всемогущество — это полнота власти благой воли.</p>`, s:SRC.dog},
  {q:"Что такое премудрость Божия?",
   a:`<p>Премудрость — совершенство Божественного разума, которым Бог знает наилучшие цели и наилучшие пути к ним и устрояет всё сообразно с ними. Она видна в устройстве творения: «Как многочисленны дела Твои, Господи! Всё соделал Ты премудро» ([[Пс 103:24]]).</p>
   <p>Высшее откровение премудрости — в деле спасения через Крест, который для мира кажется безумием, но есть «Божия премудрость» ([[1 Кор 1:24]]). Премудрость Божия часто превосходит наше разумение, и мы доверяем ей и там, где не видим её путей.</p>`, s:SRC.dog},
  {q:"Что такое святость Божия?",
   a:`<p>Святость — совершенная чистота и возвышенность Бога, Его полная непричастность злу и превосходство над всем тварным. Серафимы непрестанно взывают: «Свят, Свят, Свят Господь Саваоф» ([[Ис 6:3]]).</p>
   <p>Святость Божия — не только нравственная чистота, но и «отделённость», недоступность: приближение к Святому требует благоговения и очищения. И она же — образец и призвание для человека: «будьте святы, потому что Я свят» ([[1 Пет 1:16]]).</p>`, s:SRC.dog},
  {q:"Что такое благость Божия?",
   a:`<p>Благость — это любовь Бога, по которой Он изливает на творение бытие и всякое благо, не имея в том никакой нужды. Из благости Бог сотворил мир, из благости промышляет о нём и спасает падшего человека.</p>
   <p>«Бог есть любовь» ([[1 Ин 4:8]]); Он «благ ко всем, и щедроты Его на всех делах Его» ([[Пс 144:9]]), «повелевает солнцу Своему восходить над злыми и добрыми» ([[Мф 5:45]]). Высшее выражение благости — что Бог «Сына Своего единородного отдал» ради спасения мира ([[Ин 3:16]]).</p>`, s:SRC.dog},
  {q:"Что такое правда (правосудие) Божие?",
   a:`<p>Правда Божия — совершенная справедливость, по которой Бог требует от разумных существ добра, воздаёт каждому по делам его и хранит нравственный порядок мира. «Праведен Господь во всех путях Своих» ([[Пс 144:17]]); «Он воздаст каждому по делам его» ([[Рим 2:6]]).</p>
   <p>Правда не противоречит благости: обе соединяются в деле спасения, где Бог и грех осуждает, и грешника милует — через Крест Христов. Долготерпение Божие даёт время на покаяние, но не отменяет суда.</p>`, s:SRC.dog},
  {q:"Как согласуются свобода человека и всеведение Бога?",
   a:`<p>Бог от вечности предвидит все свободные поступки людей, но предвидение не есть принуждение. Знать заранее, как человек свободно поступит, — не значит заставить его так поступить; знание не является причиной события.</p>
   <p>Как очевидец не отнимает свободы у того, за кем наблюдает, так и всеведение Божие, объемлющее и наш выбор, оставляет его подлинно свободным. Поэтому человек несёт ответственность за свои дела, а Бог праведно судит их.</p>`, s:SRC.dog},
  {q:"Существует ли только один Бог?",
   a:`<p>Да, Бог един по существу — это основа всего Откровения. «Слушай, Израиль: Господь, Бог наш, Господь един есть» ([[Втор 6:4]]); «нет иного Бога, кроме Единого» ([[1 Кор 8:4]]). Многобожие есть заблуждение, обожествляющее творение вместо Творца.</p>
   <p>Единство Божие не противоречит троичности Лиц: Отец, Сын и Дух — не три бога, а единое Божественное существо в трёх Лицах. Об этом — раздел о Святой Троице.</p>`, s:SRC.dog},
  {q:"Почему Бог именуется Творцом?",
   a:`<p>Творцом Бог именуется потому, что Он привёл весь мир — духовный и вещественный — из небытия в бытие одной Своей волей, не из готового вещества и не по необходимости. «В начале сотворил Бог небо и землю» ([[Быт 1:1]]); «всё чрез Него начало быть» ([[Ин 1:3]]).</p>
   <p>Творение отличает библейскую веру от языческих учений о вечной материи или об истечении мира из Бога. Мир не есть ни Бог, ни часть Бога, но Его свободное создание, всецело от Него зависящее.</p>`, s:SRC.dog}
 ]
},

/* ============================ 4. ТРИАДОЛОГИЯ ============================ */
{
 id:"triadologiya", title:"Учение о Святой Троице",
 sub:"Триадология: три Лица единого Бога",
 qa:[
  {q:"Что значит, что Бог — Троица?",
   a:`<p>Христиане исповедуют единого Бога в трёх Лицах: Отец, Сын и Святой Дух. Это не три бога и не три имени одного Лица, а единое, нераздельное Божественное существо, в котором три Лица (Ипостаси) действительно различны, но совершенно единосущны и равны.</p>
   <p>Троичность — не измышление разума, а тайна, открытая Самим Богом. Господь заповедал крестить «во имя Отца и Сына и Святаго Духа» ([[Мф 28:19]]) — во единое имя трёх Лиц; апостол благословляет «благодатью Господа Иисуса Христа, и любовью Бога Отца, и общением Святаго Духа» ([[2 Кор 13:13]]).</p>`, s:SRC.dog},
  {q:"Троица — это три Бога?",
   a:`<p>Нет. Лица Троицы единосущны — они обладают одним и тем же Божественным существом, одной волей, одной силой и действием. Поэтому Бог один, а не три. Учение о трёх богах (тритеизм) Церковь решительно отвергает.</p>
   <p>Троичность относится к <em>Лицам</em>, а единство — к <em>существу</em>: три «Кто» при одном «что». Отец, Сын и Дух не разделяют Божество на части и не суть три «экземпляра» божества, но всецело обладают единым и неделимым Божеством.</p>`, s:SRC.dog},
  {q:"Чем различаются Лица Троицы?",
   a:`<p>Лица различаются не существом (оно у Них общее) и не свойствами Божества, а только <em>личными свойствами</em>, то есть образом бытия и вечными отношениями между Собою: Отец не рождён и ни от кого не происходит; Сын предвечно рождается от Отца; Дух Святой предвечно исходит от Отца.</p>
   <p>Эти отношения вечны, неизменны и не вносят в Бога ни разделения, ни «раньше» и «позже». Всё общее — у Трёх, кроме нерождённости, рождения и исхождения. Так исповедует Церковь тайну равенства и различия Лиц.</p>`, s:SRC.dog},
  {q:"Почему Сын Божий — истинный Бог?",
   a:`<p>Писание ясно усваивает Сыну всё Божественное. Он вечен и есть Творец: «В начале было Слово, и Слово было у Бога, и Слово было Бог… всё чрез Него начало быть» ([[Ин 1:1]]). Апостол Фома исповедует воскресшего Христа: «Господь мой и Бог мой» ([[Ин 20:28]]).</p>
   <p>Ему приписываются Божественные свойства и дела — прощение грехов, воскрешение мёртвых, суд над миром — и воздаётся Божеское поклонение. Отрицание Божества Сына (арианство) разрушило бы и само спасение, ибо спасти человека мог только Бог.</p>`, s:SRC.dog},
  {q:"Что значит «рождение» Сына от Отца?",
   a:`<p>Рождение Сына — вечное, духовное и бесстрастное, а не во времени и не телесное. Сын рождается от <em>существа</em> Отца, а не творится из ничего, потому Он единосущен Отцу и так же вечен, как Отец: не было такого, чтобы Отец был без Сына.</p>
   <p>Сын — «сияние славы и образ ипостаси» Отца ([[Евр 1:3]]). Отцы поясняли: как свет неотделим от солнца и вечно рождается от него, так Сын — от Отца, но это лишь несовершенное подобие непостижимой тайны.</p>`, s:SRC.dog},
  {q:"Почему Святой Дух — Бог?",
   a:`<p>Святому Духу Писание также усваивает Божественное. Апостол называет верующих храмом Божиим, «ибо Дух Божий живёт в вас» ([[1 Кор 3:16]]) — значит, Дух есть Бог. Солгавший Духу Святому, по слову Петра, «солгал не человекам, а Богу» ([[Деян 5:4]]).</p>
   <p>Слова, сказанные, по пророку Исаии, Самим Господом ([[Ис 6:9]]), апостол Павел прямо приписывает Духу Святому ([[Деян 28:25]]). Дух животворит, освящает, наставляет на всякую истину — совершает дела, свойственные одному Богу.</p>`, s:SRC.dog},
  {q:"От кого исходит Святой Дух?",
   a:`<p>По слову Самого Господа, Дух истины «от Отца исходит» ([[Ин 15:26]]). Поэтому Православная Церковь исповедует исхождение Святого Духа от Отца, как это навсегда закреплено в Никео-Цареградском Символе веры.</p>
   <p>Позднейшая западная прибавка «и от Сына» (filioque), внесённая в Символ, стала одной из причин разделения Церквей: Восток видел в ней и нарушение неизменности соборного Символа, и искажение учения о единоначалии Отца в Троице.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Что означает слово «единосущный»?",
   a:`<p>«Единосущный» (греч. <em>homoousios</em>) означает, что Сын — <em>того же самого</em> Божественного существа, что и Отец, а не только подобен Ему. Этим словом отсекается всякая мысль, будто Сын — иное, низшее или сотворённое существо.</p>
   <p>Слово внесли отцы Первого Вселенского собора в Никее (325 г.), чтобы точно оградить веру от учения Ария. Хотя самого этого слова нет в Библии, оно верно выражает библейскую истину — и в этом пример того, как Церковь на соборе даёт точные определения против ересей.</p>`, s:SRC.ist},
  {q:"Кто такой Арий и в чём его заблуждение?",
   a:`<p>Арий — александрийский пресвитер начала IV века, учивший, что Сын не вечен и не единосущен Отцу, а есть высшее творение, через которое Бог создал прочий мир («было, когда Его не было»). Тем самым он отвергал истинное Божество Христа.</p>
   <p>Против него выступил святитель Афанасий Великий. Первый Вселенский собор (325 г.) осудил арианство и исповедал Сына «рождённым, несотворённым, единосущным Отцу». Спор, однако, продолжался ещё десятилетия, пока Церковь окончательно не утвердила никейскую веру.</p>`, s:SRC.ist},
  {q:"Кто такие Каппадокийские отцы?",
   a:`<p>Так называют трёх великих богословов IV века — святителей Василия Великого, Григория Богослова и Григория Нисского. Они завершили формулировку троичного догмата, отстояв никейскую веру и разработав точный язык: одно <em>существо</em> (усия) и три <em>Лица</em> (ипостаси).</p>
   <p>Их трудами Второй Вселенский собор (381 г.) утвердил Божество Святого Духа. Святителя Григория за глубину богословия Церковь именует Богословом. Каппадокийцы показали, как хранить и единство Божие, и различие Лиц.</p>`, s:SRC.ist},
  {q:"Проявляется ли Троица в Ветхом Завете?",
   a:`<p>Прикровенно — да, хотя ясное откровение о Троице дано в Новом Завете. Отцы видели предуказания на неё в словах «сотворим человека по образу Нашему» ([[Быт 1:26]]), в троекратном «Свят» ([[Ис 6:3]]) и в явлении Аврааму трёх мужей у дуба Мамврийского ([[Быт 18:2]]).</p>
   <p>Ветхий Завет прежде всего утверждал единобожие среди язычников, поэтому тайна троичности открывалась постепенно, чтобы не подать повода к многобожию. С пришествием Христа она возвещена ясно.</p>`, s:SRC.dog},
  {q:"Как понять тайну Троицы?",
   a:`<p>Тайна Троицы превосходит тварный разум и не может быть исчерпана никаким образом или сравнением. Отеческие подобия — солнце, луч и тепло; корень, ствол и плод; ум, слово и дух в человеке — лишь отчасти помогают, но каждое в чём-то неточно.</p>
   <p>Троица не постигается, а исповедуется верой и созерцается в молитве и жизни Церкви. Само призвание человека — войти в общение любви Трёх Лиц, по молитве Христа: «да будут все едино, как Ты, Отче, во Мне, и Я в Тебе» ([[Ин 17:21]]).</p>`, s:SRC.dog}
 ]
},

/* ==================== 5. КОСМОЛОГИЯ И АНГЕЛОЛОГИЯ ==================== */
{
 id:"kosmologiya", title:"Творение, ангелы и Промысл",
 sub:"Космология, ангелология, учение о Промысле",
 qa:[
  {q:"Сотворил ли Бог мир из ничего?",
   a:`<p>Да. Мир не вечен, не самобытен и не возник сам собою: «В начале сотворил Бог небо и землю» ([[Быт 1:1]]). Словами «небо и земля» Писание охватывает весь состав созданного — мир духовный (ангельский) и вещественный.</p>
   <p>Бог творит не из готового вещества и не из Своего существа, а приводит бытие из небытия одним Своим словом: «Он сказал — и сделалось; Он повелел — и явилось» ([[Пс 32:9]]). Это учение (лат. <em>creatio ex nihilo</em>) отличает веру от языческих мифов о вечной материи и от пантеизма, растворяющего мир в Боге.</p>`, s:SRC.dog},
  {q:"Зачем Бог сотворил мир?",
   a:`<p>Не по нужде и не для восполнения Себя, ибо Бог всесовершен, всеблажен и самодостаточен. Мир сотворён по одной благости — чтобы разделить дар бытия и блаженства с творением, вызвать к жизни существа, способные познавать и любить Бога.</p>
   <p>Поэтому конечная цель мира — слава Божия, являемая в творении, и блаженство разумных существ в общении с Богом. «Достоин Ты, Господи, приять славу… ибо Ты сотворил всё» ([[Откр 4:11]]).</p>`, s:SRC.dog},
  {q:"Что означают «шесть дней» творения?",
   a:`<p>Шестоднев ([[Быт 1:1]]) изображает разумный, восходящий порядок творения — от простого к сложному, от неодушевлённого к живому, и до человека как венца. Он утверждает, что мир создан не случайно, а по премудрому замыслу единого Бога.</p>
   <p>«Дни» отцы толковали по-разному: одни — как обычные сутки, другие (например, блаженный Августин) — как ступени, не сводимые к нашему счёту времени. Церковь не связывает веру с одним толкованием длительности, но твёрдо исповедует, что Творец всего — Бог, и что человек создан Им особо.</p>`, s:SRC.dog},
  {q:"Совместима ли вера с научными данными о возрасте мира?",
   a:`<p>Да. Писание учит не о «как» и «когда» в научном смысле, а о том, <em>Кто</em> и <em>зачем</em> сотворил мир. Оно говорит о творении языком, доступным древнему читателю, и не является учебником физики или биологии.</p>
   <p>Поэтому данные науки о возрасте вселенной и о развитии жизни не противоречат вере в Бога-Творца: верующий видит в естественных законах и процессах <em>способ</em>, которым осуществляется Божий замысел. Главное неизменно: мир не самобытен, а сотворён, и человек — особое создание Божие.</p>`, s:SRC.dog},
  {q:"Кто такие ангелы?",
   a:`<p>Ангелы — сотворённый Богом мир чистых, бесплотных, разумных и свободных духов, превосходящих человека силою и ведением. Они не самобытны и не вечны по природе: как и всё, получили бытие от Творца, Который создал «всё… видимое и невидимое» ([[Кол 1:16]]).</p>
   <p>Само слово «ангел» значит «вестник» и указывает не столько на природу, сколько на служение. Ангелы сотворены прежде вещественного мира и предназначены к славословию Бога и служению Его Промыслу.</p>`, s:SRC.dog},
  {q:"Каково служение ангелов?",
   a:`<p>Ангелы непрестанно предстоят Богу, славословят Его и исполняют Его волю, а также посылаются на служение людям ко спасению: «не все ли они суть служебные духи, посылаемые на служение для тех, которые имеют наследовать спасение?» ([[Евр 1:14]]).</p>
   <p>Они возвещали волю Божию пророкам, служили Христу, укрепляли апостолов. По слову Господа, каждому верующему дан ангел-хранитель: «Ангелы их на небесах всегда видят лице Отца Моего» ([[Мф 18:10]]).</p>`, s:SRC.dog},
  {q:"Есть ли у ангелов чины?",
   a:`<p>Да, ангельский мир не однороден, а иерархичен. Писание называет разные чины: херувимов, серафимов, престолы, господства, начала, власти, силы, архангелов и ангелов ([[Кол 1:16]], [[Ис 6:2]]).</p>
   <p>Церковное Предание, следуя святому Дионисию Ареопагиту, различает девять ангельских чинов, объединённых в три степени (иерархии). Из архангелов Писание называет по имени Михаила ([[Иуд 1:9]]) и Гавриила ([[Лк 1:26]]).</p>`, s:SRC.pred},
  {q:"Откуда произошли злые духи?",
   a:`<p>Диавол и бесы — не изначальное зло и не «второе божество»: они сотворены Богом добрыми ангелами, но добровольно отпали от Него по гордости и злоупотреблению свободой. Зло не имеет собственной природы; оно есть повреждение доброго.</p>
   <p>Господь сказал: «Я видел сатану, спадшего с неба, как молнию» ([[Лк 10:18]]); апостол пишет об ангелах, которые «не сохранили своего достоинства, но оставили своё жилище» ([[Иуд 1:6]]). Падшие духи ожесточились во зле окончательно.</p>`, s:SRC.dog},
  {q:"Может ли диавол принудить человека ко греху?",
   a:`<p>Нет. Власть диавола ограничена: он может искушать, соблазнять, внушать помыслы, но не может принудить свободную волю человека без его согласия. Грех совершается лишь тогда, когда человек сам склоняется на искушение.</p>
   <p>Поэтому Писание призывает к трезвению и сопротивлению: «Противостаньте диаволу, и убежит от вас» ([[Иак 4:7]]); «облекитесь во всеоружие Божие» ([[Еф 6:11]]). Оружие против искушений — вера, молитва, смирение и благодать.</p>`, s:SRC.dog},
  {q:"Что такое Промысл Божий?",
   a:`<p>Промысл — это непрестанное действие Божие, которым Бог сохраняет бытие мира, содействует всему доброму и премудро направляет всё ко благой цели. Бог не сотворил мир, чтобы затем оставить его: «Отец Мой доныне делает, и Я делаю» ([[Ин 5:17]]).</p>
   <p>Промысл объемлет и великое, и малое: без воли Отца «и волос с головы не упадёт» ([[Лк 21:18]]), и малая птица не забыта у Бога ([[Мф 10:29]]). Различают <em>сохранение</em> (Бог поддерживает бытие) и <em>управление</em> (Бог ведёт мир к цели).</p>`, s:SRC.dog},
  {q:"Не отменяет ли Промысл свободу человека?",
   a:`<p>Нет. Промысл действует, не насилуя свободы разумных существ. Бог содействует добру, попускает (но не производит) зло и обращает даже злые поступки людей ко благим последствиям, не отнимая у них ответственности.</p>
   <p>Ярчайший пример — история Иосифа: братья умышляли против него зло, «а Бог обратил это в добро» ([[Быт 50:20]]). Так свободная воля человека и премудрый Промысл Божий соединяются, не упраздняя друг друга.</p>`, s:SRC.dog},
  {q:"Почему праведные страдают, а нечестивые благоденствуют?",
   a:`<p>Этот вопрос волновал ещё псалмопевца и праведного Иова. Ответ веры в том, что видимое не есть окончательное: пути Промысла глубоки и не всегда открыты нам сразу. Страдание праведных бывает очищением, испытанием и возрастанием, а благополучие злых — временно и обманчиво.</p>
   <p>Псалмопевец, смущавшийся счастьем нечестивых, успокоился, «когда вошёл во святилище Божие и уразумел конец их» ([[Пс 72:17]]). Полная правда откроется в будущей жизни, где каждому воздастся по делам. Доверие благому Промыслу — не отказ от вопросов, а мир среди них.</p>`, s:SRC.dog}
 ]
},

/* ============================ 6. АНТРОПОЛОГИЯ ============================ */
{
 id:"antropologiya", title:"Учение о человеке",
 sub:"Антропология: образ Божий, душа, назначение",
 qa:[
  {q:"Каким сотворён человек?",
   a:`<p>Человек создан особым советом и действием Божиим как венец видимого творения. В отличие от прочих тварей, вызванных к бытию словом, о человеке сказано: «сотворим человека по образу Нашему и по подобию Нашему» ([[Быт 1:26]]).</p>
   <p>Он сотворён из двух начал: тело — из «праха земного», а душа — вдунута Богом ([[Быт 2:7]]), почему человек соединяет в себе мир вещественный и духовный. Ему дано владычество над землёй и призвание жить в общении с Богом. Первоначально человек был чист, безгрешен и предназначен к бессмертию.</p>`, s:SRC.dog},
  {q:"Что такое образ Божий в человеке?",
   a:`<p>Образ Божий — это богоподобное устроение человеческой души: разум, свободная воля, способность любить и творить, совесть, бессмертие духа, дар владычества. Этими чертами человек отражает своего Создателя и превосходит прочую тварь.</p>
   <p>Образ дан всем людям и не утрачивается вполне даже во грехе, хотя и помрачается. Именно ради образа Божия священна всякая человеческая жизнь, и потому апостол запрещает злословить людей, «сотворённых по подобию Божию» ([[Иак 3:9]]).</p>`, s:SRC.dog},
  {q:"Чем различаются образ и подобие?",
   a:`<p>Многие отцы различали эти слова так: <em>образ</em> — это данное человеку от сотворения богоподобное устроение (разум, свобода, бессмертие), а <em>подобие</em> — это задача, цель: уподобляться Богу в святости, любви и добродетели, осуществляемая свободным произволением.</p>
   <p>Иначе говоря, образ есть у каждого как дар, а подобие достигается жизнью по Богу как плод сотрудничества с благодатью. Христос указал предел этого возрастания: «Будьте совершенны, как совершен Отец ваш Небесный» ([[Мф 5:48]]).</p>`, s:SRC.dog},
  {q:"Что такое душа?",
   a:`<p>Душа — разумное, свободное, бессмертное духовное начало человека, которое оживляет тело, познаёт, чувствует и стремится к Богу. Она сотворена Богом и не происходит из вещества; в ней прежде всего запечатлён образ Божий.</p>
   <p>По разлучении с телом душа не уничтожается, но продолжает жить и сознавать. Господь предостерегает беречь душу превыше всего: «какая польза человеку, если он приобретёт весь мир, а душе своей повредит?» ([[Мф 16:26]]).</p>`, s:SRC.dog},
  {q:"Из чего состоит человек — из двух частей или трёх?",
   a:`<p>Человек есть единство души и тела — это основное, «дихотомическое» деление. Вместе с тем апостол говорит о «духе, душе и теле» ([[1 Фес 5:23]]), и некоторые отцы различают в человеке три стороны, понимая «дух» как высшую часть души, обращённую к Богу.</p>
   <p>Оба способа выражения согласны в главном: человек — не только тело и не только душа, а их живое единство, и высшее в нём — способность к богообщению. Тело при этом не темница и не зло, а храм, предназначенный к воскресению.</p>`, s:SRC.dog},
  {q:"Бессмертна ли душа?",
   a:`<p>Да, душа бессмертна — не по своей природе как нечто «самобожественное», а по дару и воле Божией. По смерти тела она продолжает жить, сознавать и помнить, ожидая всеобщего воскресения.</p>
   <p>Господь есть «Бог не мёртвых, но живых» ([[Мф 22:32]]); благоразумному разбойнику Он обещал: «ныне же будешь со Мною в раю» ([[Лк 23:43]]). При этом полнота человека восстановится, когда в последний день воскреснет и тело.</p>`, s:SRC.dog},
  {q:"В чём назначение человека?",
   a:`<p>Назначение человека — знать, любить и прославлять Бога, возрастать в уподоблении Ему и в общении с Ним достигать вечного блаженства. Человек создан не для себя самого и не для мира, а для Бога, и лишь в Нём находит полноту.</p>
   <p>Блаженный Августин выразил это словами: «Ты создал нас для Себя, и не знает покоя сердце наше, пока не успокоится в Тебе». Высшая цель — обожение, приобщение Божественной жизни по благодати ([[2 Пет 1:4]]).</p>`, s:SRC.dog},
  {q:"Что такое совесть?",
   a:`<p>Совесть — вложенный Богом внутренний закон, которым человек различает добро и зло, судит свои поступки и понуждается к добру. Она есть и у не знавших писаного закона: у язычников «дело закона написано в сердцах» ([[Рим 2:15]]).</p>
   <p>Совесть можно заглушить и исказить грехом, поэтому её нужно хранить чистой и просвещать словом Божиим и жизнью в Церкви. Чистая совесть — великое благо: апостол дорожит тем, чтобы «иметь непорочную совесть пред Богом и людьми» ([[Деян 24:16]]).</p>`, s:SRC.dog},
  {q:"Что такое свобода воли?",
   a:`<p>Свобода воли — данная человеку от сотворения способность самоопределения, выбора между добром и злом. Без неё не было бы ни нравственности, ни заслуги, ни ответственности; она — часть образа Божия и условие любви, ибо любовь возможна только свободная.</p>
   <p>«Бог от начала… оставил его в руке произволения его» ([[Сир 15:14]]); человеку предложено: «избери жизнь» ([[Втор 30:19]]). Грех повредил свободу, склонив её ко злу, но благодать исцеляет и восстанавливает её.</p>`, s:SRC.dog},
  {q:"Едины ли все люди по происхождению?",
   a:`<p>Да, всё человечество происходит от одной четы прародителей и составляет единый род. Бог «от одной крови произвёл весь род человеческий для обитания по всему лицу земли» ([[Деян 17:26]]).</p>
   <p>Это единство — основание всеобщего братства людей, равного достоинства всех народов и всеобщности как греха, так и спасения: как в Адаме все умирают, так во Христе все оживут ([[1 Кор 15:22]]). Родство языков и народов подтверждает это первоначальное единство.</p>`, s:SRC.dog}
 ]
},

/* ============================ 7. АМАРТОЛОГИЯ ============================ */
{
 id:"amartologiya", title:"Учение о грехе",
 sub:"Амартология: грехопадение и его следствия",
 qa:[
  {q:"Что такое грех?",
   a:`<p>Грех — это нарушение воли Божией, свободное уклонение разумного существа от добра и от Бога. «Всякий, делающий грех, делает и беззаконие; и грех есть беззаконие» ([[1 Ин 3:4]]).</p>
   <p>Грех — не самостоятельная сущность и не создан Богом; это порча, лишение и искажение блага, как тьма есть отсутствие света, а болезнь — расстройство здоровья. Корень греха — в злоупотреблении свободой, в предпочтении себя и твари Богу.</p>`, s:SRC.dog},
  {q:"В чём состояло грехопадение прародителей?",
   a:`<p>Первые люди преступили единственную данную им заповедь, вкусив по внушению искусителя от древа познания добра и зла ([[Быт 3:6]]). Внешне малый поступок был по сути тяжким: отвержением доверия и послушания Богу.</p>
   <p>Существо падения — в гордости и своеволии: человек пожелал «быть как боги» ([[Быт 3:5]]), стать самому себе законом и источником блага помимо Бога. Так тварь поставила себя на место Творца — в этом корень всякого греха.</p>`, s:SRC.dog},
  {q:"Каковы следствия грехопадения?",
   a:`<p>Через грех расстроилась вся жизнь человека и мира. Помрачился ум, ослабела и склонилась ко злу воля, взбунтовались страсти, разрушилось согласие с Богом, с ближними и с самим собою. В мир вошли тление и смерть: «возмездие за грех — смерть» ([[Рим 6:23]]).</p>
   <p>Человек был изгнан из рая — из состояния близости к Богу — и земля стала произращать «терния и волчцы» ([[Быт 3:18]]). Повреждение коснулось и природы, которая «покорилась суете» ([[Рим 8:20]]) и ожидает избавления вместе с человеком.</p>`, s:SRC.dog},
  {q:"Что такое первородный грех?",
   a:`<p>Первородный грех — это унаследованная всеми потомками Адама повреждённость человеческой природы: удобопреклонность ко злу, страстность, смертность. Не грех Адама как личный поступок, а его <em>последствия</em> переходят на весь род.</p>
   <p>«Как одним человеком грех вошёл в мир, и грехом смерть, так и смерть перешла во всех человеков, потому что в нём все согрешили» ([[Рим 5:12]]). От этой повреждённости никто не свободен сам собою; исцеляет её только Христос, новый Адам.</p>`, s:SRC.dog},
  {q:"Виновен ли младенец в первородном грехе?",
   a:`<p>Младенец не несёт личной вины за грех Адама — он его не совершал. Но он наследует повреждённую, смертную природу и потому нуждается в возрождении крещением, вводящим его в новую жизнь во Христе.</p>
   <p>О детях Господь говорит с особой любовью: «пустите детей приходить ко Мне… ибо таковых есть Царство Небесное» ([[Мф 19:14]]). Крещение младенцев и есть исполнение этого призыва — приведение их ко Христу.</p>`, s:SRC.dog},
  {q:"Чем различаются грехи по тяжести?",
   a:`<p>Грехи различаются и по виду (делом, словом, мыслью), и по произволению (вольные и невольные), и по тяжести. Апостол Иоанн различает грех «к смерти» и грех «не к смерти» ([[1 Ин 5:16]]) — по мере ожесточения воли и удаления от Бога.</p>
   <p>Тяжкими (смертными) называют грехи, которые, если в них коснеть без покаяния, отлучают от благодати и духовно умерщвляют душу. Но никакая тяжесть греха не превышает милости Божией к искренне кающемуся.</p>`, s:SRC.dog},
  {q:"Что такое страсть?",
   a:`<p>Страсть — это укоренившаяся, ставшая как бы второй природой греховная склонность, порабощающая волю и разум. Аскетическая традиция называет восемь главных страстей: чревоугодие, блуд, сребролюбие, гнев, печаль, уныние, тщеславие и гордость.</p>
   <p>Страсть начинается с помысла, через согласие переходит в дело, а через повторение — в навык и рабство: «кто кем побеждён, тот тому и раб» ([[2 Пет 2:19]]). Врачуются страсти покаянием, воздержанием и противоположными им добродетелями при помощи благодати.</p>`, s:SRC.dog},
  {q:"Есть ли непростительный грех?",
   a:`<p>Непростителен, по слову Господа, не какой-либо отдельный грех сам по себе, а «хула на Духа Святого» ([[Мф 12:31]]). Отцы понимают под ней сознательное, упорное противление явной истине и отвержение самой спасающей благодати.</p>
   <p>Такой грех «не прощается» не потому, что превышает милость Божию, а потому, что человек сам не хочет каяться и принимать прощение. Всякому же, кто кается, прощается любой грех: «приходящего ко Мне не изгоню вон» ([[Ин 6:37]]).</p>`, s:SRC.dog},
  {q:"Может ли человек сам, без Бога, победить грех?",
   a:`<p>Нет. Повреждённая грехом природа не исцеляется одними человеческими усилиями: воля ослаблена и склонна ко злу. Для победы над грехом необходима благодать Божия, подаваемая во Христе и в таинствах Церкви.</p>
   <p>Господь прямо говорит: «без Меня не можете делать ничего» ([[Ин 15:5]]); апостол исповедует: «всё могу в укрепляющем меня Иисусе Христе» ([[Флп 4:13]]). Спасение — дело и Божией благодати, и свободного человеческого произволения (синергия).</p>`, s:SRC.dog},
  {q:"Если грех так силён, есть ли надежда?",
   a:`<p>Да, и вся весть Евангелия — об этой надежде. Как ни глубоко повреждение, милость Божия и сила Христова больше: «когда умножился грех, стала преизобиловать благодать» ([[Рим 5:20]]).</p>
   <p>Христос пришёл именно «грешников спасти» ([[1 Тим 1:15]]) и «взыскать и спасти погибшее» ([[Лк 19:10]]). Поэтому учение о грехе не ведёт к унынию, а обращает человека к Спасителю и к покаянию, которое всегда открыто.</p>`, s:SRC.dog}
 ]
},

/* ============================ 8. ХРИСТОЛОГИЯ ============================ */
{
 id:"hristologiya", title:"Учение о Христе",
 sub:"Христология: воплощение и две природы",
 qa:[
  {q:"Кто такой Иисус Христос?",
   a:`<p>Иисус Христос — воплотившийся Сын Божий, второе Лицо Святой Троицы, ставший человеком ради нашего спасения. Он есть истинный Бог и истинный человек в одном Лице — Богочеловек.</p>
   <p>«Слово стало плотию и обитало с нами, полное благодати и истины» ([[Ин 1:14]]). Он — обещанный от века Мессия, Спаситель мира, Глава Церкви и Судия живых и мёртвых. В Нём «обитает вся полнота Божества телесно» ([[Кол 2:9]]).</p>`, s:SRC.dog},
  {q:"Что означает имя «Иисус Христос»?",
   a:`<p>«Иисус» — личное имя, означающее «Господь спасает»; ангел объяснил его так: «наречёшь Ему имя Иисус, ибо Он спасёт людей Своих от грехов их» ([[Мф 1:21]]).</p>
   <p>«Христос» — не фамилия, а звание (греч. перевод евр. «Мессия»), означающее «Помазанник». В Ветхом Завете помазанием поставляли царей, первосвященников и пророков. Христос совмещает все три служения: Он — Царь, вечный Первосвященник и Пророк, помазанный не елеем, а Духом Святым ([[Лк 4:18]]).</p>`, s:SRC.dog},
  {q:"Как в Христе соединены две природы?",
   a:`<p>В едином Лице Христа Божественная и человеческая природы соединены, по определению IV Вселенского собора (Халкидон, 451 г.), «неслитно, неизменно, нераздельно, неразлучно». Это значит: природы не смешиваются в некую третью, но и не разделяются на два лица.</p>
   <p>Христос — не Бог, «вселившийся» в человека, и не человек, «ставший» Богом, а единое Лицо Сына Божия, вечно сущего Богом и во времени воспринявшего полное человечество. Он не перестал быть тем, чем был, и стал тем, чем не был, — не умалив Божества и не поглотив человечества.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Истинный ли человек Христос?",
   a:`<p>Да, Христос воспринял полную и подлинную человеческую природу — тело и разумную душу, — во всём подобную нашей, кроме греха. Он рос, алкал, жаждал, утруждался, скорбел, плакал ([[Ин 11:35]]), испытывал страх пред страданием.</p>
   <p>Это не второстепенно, а необходимо для спасения: по слову отцов, «невоспринятое неисцелимо» — Христос должен был воспринять всё человеческое, чтобы всё исцелить. «Он подобно нам искушён во всём, кроме греха» ([[Евр 4:15]]). Отрицавшие реальность Его плоти (докеты) подрывали и самое спасение.</p>`, s:SRC.dog},
  {q:"Сколько во Христе воль и действий?",
   a:`<p>Две — Божественная и человеческая, ибо каждая совершенная природа имеет свою волю и своё действие. Но человеческая воля Христа не противится Божественной, а свободно и всецело с нею согласна.</p>
   <p>Это ясно в Гефсимании: «не Моя воля, но Твоя да будет» ([[Лк 22:42]]) — здесь человеческая воля Христа свободно предаёт себя воле Отца. Учение о двух волях исповедал VI Вселенский собор (681 г.) против монофелитства (учения об одной воле).</p>`, s:SRC.ist},
  {q:"Зачем Сын Божий стал человеком?",
   a:`<p>Чтобы спасти человека изнутри — не извне, повелением, а войдя в самую человеческую природу, исцелив её и соединив с Богом. Пал человек — и Спаситель стал человеком; поражена была смертью человеческая природа — и Бог воспринял её, чтобы победить смерть.</p>
   <p>Отцы выразили цель воплощения так: «Бог стал человеком, чтобы человек стал богом» — то есть чтобы приобщился Божественной жизни по благодати. Христос пришёл «взыскать и спасти погибшее» ([[Лк 19:10]]) и явить любовь Божию: «так возлюбил Бог мир, что отдал Сына Своего единородного» ([[Ин 3:16]]).</p>`, s:SRC.dog},
  {q:"Что такое Благовещение и бессеменное зачатие?",
   a:`<p>Благовещение — весть архангела Гавриила Деве Марии о том, что Она станет Матерью Сына Божия. На Её недоумение о том, как это будет, ангел ответил: «Дух Святый найдёт на Тебя, и сила Всевышнего осенит Тебя» ([[Лк 1:35]]).</p>
   <p>Христос зачат не от мужа, а наитием Святого Духа, потому рождён без греха и как истинный человек, и как истинный Бог. Дева свободно приняла волю Божию: «се, Раба Господня; да будет Мне по слову твоему» ([[Лк 1:38]]).</p>`, s:SRC.dog},
  {q:"Кто такая Дева Мария по отношению ко Христу?",
   a:`<p>Пресвятая Дева Мария — Матерь воплотившегося Сына Божия, а потому именуется <em>Богородицей</em>. Она родила по плоти не «простого человека», а единое Лицо Богочеловека, поэтому именование это относится к тайне воплощения.</p>
   <p>Наименование «Богородица» утвердил III Вселенский собор (Ефес, 431 г.) против Нестория, который хотел называть Её лишь «Христородицей». Ещё праведная Елисавета назвала Её «Матерью Господа» ([[Лк 1:43]]).</p>`, s:SRC.ist},
  {q:"Был ли Христос предсказан в Ветхом Завете?",
   a:`<p>Да, весь Ветхий Завет — приготовление к Мессии и полон пророчеств о Нём. Предсказаны Его рождение от Девы ([[Ис 7:14]]) и в Вифлееме ([[Мих 5:2]]), Его служение, страдания и смерть за грехи ([[Ис 53:5]]), новый завет ([[Иер 31:31]]).</p>
   <p>Исполнение этих пророчеств во Христе — сильное свидетельство истины веры. Сам воскресший Господь, «начав от Моисея, из всех пророков изъяснял им сказанное о Нём во всём Писании» ([[Лк 24:27]]).</p>`, s:SRC.dog},
  {q:"Что такое кенозис (умаление) Христа?",
   a:`<p>Кенозис (греч. «истощание», «умаление») — добровольное самоумаление Сына Божия в воплощении, когда Он, «будучи образом Божиим… уничижил Себя Самого, приняв образ раба… смирил Себя, быв послушным даже до смерти, и смерти крестной» ([[Флп 2:6]]).</p>
   <p>Это не значит, что Сын перестал быть Богом или утратил Божественные свойства. Он скрыл славу под смирением, добровольно принял немощи человеческой природы (голод, усталость, страдание, смерть), чтобы разделить нашу участь и спасти нас.</p>`, s:SRC.dog},
  {q:"Почему монофизитство и несторианство — заблуждения?",
   a:`<p>Это две противоположные крайности. <em>Несторианство</em> так разделяло природы, что во Христе получались как бы два лица — Бог и человек, лишь соединённые; тогда Дева была бы Матерью человека, а не Бога, и спасал бы нас человек.</p>
   <p><em>Монофизитство</em>, напротив, сливало природы, утверждая одну (Божественную), поглотившую человеческую; тогда человек не был бы вполне воспринят, а значит, и не исцелён. Церковь исповедует срединную истину: одно Лицо в двух полных, неслитных и нераздельных природах.</p>`, s:SRC.ist},
  {q:"Что означает сошествие Христа во ад?",
   a:`<p>После смерти на Кресте Христос телом пребывал во гробе, а душою сошёл в ад — в область умерших — и там проповедал победу над смертью, изведя ветхозаветных праведников, ожидавших Спасителя.</p>
   <p>Апостол пишет, что Христос, «быв умерщвлён по плоти, но ожив духом, … находящимся в темнице духам, сойдя, проповедал» ([[1 Пет 3:18]]). Так спасение простёрлось и на живших до пришествия Христова. Икона Воскресения изображает именно это — Христа, изводящего Адама и Еву из ада.</p>`, s:SRC.dog},
  {q:"Почему Воскресение Христово так важно?",
   a:`<p>Воскресение — сердцевина христианской веры и залог нашего собственного воскресения. Им подтверждается, что Христос — Сын Божий, что жертва Его принята и что смерть побеждена. Без него всё рушится: «если Христос не воскрес, то и проповедь наша тщетна, тщетна и вера ваша» ([[1 Кор 15:14]]).</p>
   <p>Но Христос воистину воскрес «как первенец из умерших» ([[1 Кор 15:20]]) — первый из людей, восставший в прославленном теле, за Которым последуем и мы. Апостолы были очевидцами Воскресшего и запечатлели это свидетельство своей кровью.</p>`, s:SRC.dog},
  {q:"Что такое Вознесение Господне?",
   a:`<p>По Воскресении, в сороковой день, Христос в прославленном человеческом теле вознёсся на небо и «воссел одесную Бога» ([[Мк 16:19]]). Этим человеческая природа введена в самую славу Божию — залог того, что и человек призван к небесной славе.</p>
   <p>Вознесясь, Христос не оставил учеников, но обещал пребывать с ними «во все дни до скончания века» ([[Мф 28:20]]) и послать Духа Утешителя. Ангелы возвестили, что Он придёт вновь так же, как вознёсся ([[Деян 1:11]]).</p>`, s:SRC.dog},
  {q:"Придёт ли Христос снова?",
   a:`<p>Да, Церковь исповедует, что Христос «паки грядущаго со славою судити живым и мёртвым». Второе пришествие будет не в уничижении, как первое, а в славе и силе, видимо для всех: «как молния исходит от востока и видна бывает даже до запада, так будет пришествие Сына Человеческого» ([[Мф 24:27]]).</p>
   <p>Тогда совершится всеобщее воскресение и последний суд, и настанет вечное Царство, которому «не будет конца». О времени же пришествия «никто не знает» ([[Мф 24:36]]), и потому Господь велит бодрствовать.</p>`, s:SRC.pred}
 ]
},

/* ============================ 9. СОТЕРИОЛОГИЯ ============================ */
{
 id:"soteriologiya", title:"Учение о спасении",
 sub:"Сотериология: искупление, благодать, оправдание",
 qa:[
  {q:"Что такое спасение?",
   a:`<p>Спасение — это избавление человека от греха, проклятия и смерти и восстановление разрушенного общения с Богом, ведущее к вечной жизни и блаженству. Оно совершено Христом объективно и усваивается каждым человеком лично — верой, покаянием и жизнью в Церкви.</p>
   <p>Спасение не только прощение вины, но и исцеление природы и её приобщение Богу. «Нет другого имени под небом, данного человекам, которым надлежало бы нам спастись» ([[Деян 4:12]]) — источник спасения один, Христос.</p>`, s:SRC.dog},
  {q:"Что такое искупление?",
   a:`<p>Искупление — совершённое Христом дело избавления людей от рабства греху, проклятию закона и власти смерти ценою Его крестной жертвы. Слово указывает на освобождение как бы «выкупом»: «Сын Человеческий пришёл… отдать душу Свою для искупления многих» ([[Мф 20:28]]).</p>
   <p>«Христос искупил нас от клятвы закона, сделавшись за нас клятвою» ([[Гал 3:13]]). Искупление — не «сделка» с диаволом и не «умилостивление гневного Бога» в языческом смысле, а дело любви Божией, врачующей грех и примиряющей человека с Богом.</p>`, s:SRC.dog},
  {q:"Почему для спасения нужен был Крест?",
   a:`<p>Крест — добровольная жертва совершенной любви и послушания, которой Христос понёс на Себе последствия греха всего человечества и «грехи наши вознёс телом Своим на древо» ([[1 Пет 2:24]]). В Кресте соединились правда Божия (грех осуждён) и любовь Божия (грешник помилован).</p>
   <p>Крест не был необходимостью, извне навязанной Богу; это путь, избранный любовью, чтобы победить зло не силой, а самоотдачей. «Нет больше той любви, как если кто положит душу свою за друзей своих» ([[Ин 15:13]]). Через смерть Христос упразднил смерть.</p>`, s:SRC.dog},
  {q:"Что такое благодать?",
   a:`<p>Благодать — это нетварная спасительная сила и дар Божий, действием Святого Духа возрождающий, освящающий и укрепляющий человека. Она даётся не за заслуги, а по любви Божией: «благодатью вы спасены через веру, и сие не от вас, Божий дар» ([[Еф 2:8]]).</p>
   <p>Благодать не есть тварная «вещь» и не действует помимо человека магически; она — Сам Бог в Своих действиях (энергиях), исцеляющий природу и подающий силы к добру. Без благодати человек не может ни начать, ни совершить спасения.</p>`, s:SRC.dog},
  {q:"Как соотносятся благодать и свобода человека?",
   a:`<p>Спасение совершается как <em>синергия</em> — соработничество Божией благодати и свободного произволения человека. Благодать не насилует воли и не спасает человека помимо него, а человек без благодати бессилен.</p>
   <p>«Мы соработники у Бога» ([[1 Кор 3:9]]); «бодрствуйте и молитесь» ([[Мф 26:41]]). Образ этого — виноградная лоза и ветви: жизнь идёт от лозы (Христа), но ветвь должна пребывать на ней и приносить плод ([[Ин 15:5]]). Ни благодать без свободы, ни свобода без благодати не спасают.</p>`, s:SRC.dog},
  {q:"Спасаемся ли мы верой или делами?",
   a:`<p>Спасает вера — но живая, действующая любовью ([[Гал 5:6]]) и приносящая плоды. Дела не «покупают» спасение и не заслуживают его как плату, но необходимы как свидетельство и проявление подлинной веры.</p>
   <p>Апостол Павел учит, что человек оправдывается верой, а не делами закона ([[Рим 3:28]]); апостол Иаков дополняет: «вера без дел мертва» ([[Иак 2:26]]). Противоречия нет: спасает благодать через веру, а живая вера непременно рождает добрые дела.</p>`, s:SRC.dog},
  {q:"Что такое оправдание?",
   a:`<p>Оправдание — это дарованное Богом во Христе прощение грехов и принятие человека в милость, соединённое с внутренним обновлением и началом новой жизни. В православном понимании оправдание неотделимо от освящения: Бог не только «объявляет» грешника праведным, но и реально претворяет его.</p>
   <p>«Оправдавшись верою, мы имеем мир с Богом через Господа нашего Иисуса Христа» ([[Рим 5:1]]). Начало оправдания подаётся в крещении, а возрастает оно во всей христианской жизни.</p>`, s:SRC.dog},
  {q:"Что такое освящение?",
   a:`<p>Освящение — это постепенное преображение верующего благодатью Святого Духа, возрастание в святости, очищение от страстей и уподобление Христу. Оно — цель и содержание всей христианской жизни: «воля Божия есть освящение ваше» ([[1 Фес 4:3]]).</p>
   <p>Освящение совершается через таинства, молитву, борьбу со грехом и дела любви — при непрестанном действии благодати. Оно начинается в крещении и не завершается в этой жизни, устремляясь к совершенству в вечности.</p>`, s:SRC.dog},
  {q:"Что такое обо́жение (теосис)?",
   a:`<p>Обожение — высшая цель спасения: приобщение человека Божественной жизни, когда он благодатью становится «причастником Божеского естества» ([[2 Пет 1:4]]). Это не превращение человека в Бога по существу (что невозможно), а приобщение нетварной благодати Божией.</p>
   <p>Отцы выразили это так: «Бог стал человеком, чтобы человек стал богом» — по благодати, а не по природе. Обоженный человек весь пронизан благодатью, как раскалённое железо — огнём, оставаясь железом. К этому призван каждый: «будьте совершенны, как совершен Отец ваш Небесный» ([[Мф 5:48]]).</p>`, s:SRC.pred},
  {q:"Спасение уже совершилось или ещё продолжается?",
   a:`<p>И то и другое. Объективно спасение <em>совершено</em> Христом раз навсегда: искупление, победа над смертью — это уже данность. Но каждому человеку его ещё предстоит <em>усвоить</em> и в нём пребыть; поэтому Писание говорит о спасении и как о совершившемся, и как о совершающемся, и как о будущем.</p>
   <p>«Со страхом и трепетом совершайте своё спасение» ([[Флп 2:12]]), — пишет апостол уже верующим. Христианин спасён (в крещении), спасается (в жизни по вере) и будет спасён (в вечности).</p>`, s:SRC.dog},
  {q:"Может ли спасённый снова погибнуть?",
   a:`<p>Да — спасение не есть безусловная «гарантия», действующая помимо свободы. Человек, приобщившийся благодати, может отпасть от неё нерадением, тяжким грехом, отречением от веры. Поэтому Писание постоянно предостерегает и призывает к бодрствованию.</p>
   <p>«Кто думает, что он стоит, берегись, чтобы не упасть» ([[1 Кор 10:12]]); «будь верен до смерти, и дам тебе венец жизни» ([[Откр 2:10]]). Но и отпавший может восстать покаянием — двери милосердия открыты до конца жизни.</p>`, s:SRC.dog},
  {q:"Спасутся ли те, кто не слышал о Христе?",
   a:`<p>Окончательный суд принадлежит одному Богу, «Который хочет, чтобы все люди спаслись и достигли познания истины» ([[1 Тим 2:4]]). Церковь возвещает, что спасение — во Христе, но не берётся ограничивать милость Божию и судить участь неведавших.</p>
   <p>Апостол говорит, что язычники, не имевшие закона, будут судимы по совести и по тому свету, который имели ([[Рим 2:14]]). Бог праведен и благ; наше дело — не выносить приговоров, а возвещать Евангелие и вверять всех Его милосердию.</p>`, s:SRC.dog}
 ]
},

/* ============================ 10. ПНЕВМАТОЛОГИЯ ============================ */
{
 id:"pnevmatologiya", title:"Учение о Святом Духе",
 sub:"Пневматология: Дух Святой и Его действие",
 qa:[
  {q:"Кто такой Святой Дух?",
   a:`<p>Святой Дух — третье Лицо Пресвятой Троицы, истинный Бог, единосущный Отцу и Сыну, предвечно исходящий от Отца. Символ веры называет Его «Господом Животворящим» — Тот, Кто подаёт и поддерживает жизнь.</p>
   <p>Дух не безличная «сила» или «энергия», а Личность: Он говорит, посылает, наставляет, скорбит, раздаёт дары «каждому особо, как Ему угодно» ([[1 Кор 12:11]]). Он освящает Церковь и наставляет её «на всякую истину» ([[Ин 16:13]]).</p>`, s:SRC.dog},
  {q:"Что такое Пятидесятница?",
   a:`<p>Пятидесятница — сошествие Святого Духа на апостолов в пятидесятый день по Воскресении Христовом, в виде огненных языков ([[Деян 2:3]]). Исполнившись Духа, апостолы стали безбоязненно проповедовать Христа на разных языках, и в тот день крестилось около трёх тысяч человек.</p>
   <p>С этого события начинается открытая жизнь Церкви в мире, потому Пятидесятницу называют днём её рождения. Праздник этот — Троицын день — прославляет полноту откровения Троицы.</p>`, s:SRC.ist},
  {q:"Как Дух Святой действует в Церкви?",
   a:`<p>Дух Святой — душа Церкви: Он пребывает в ней постоянно, совершает таинства, поставляет служителей, подаёт дары, наставляет в истине и освящает верующих. Всё живое и спасительное в Церкви — действие Духа.</p>
   <p>Церковь есть храм, в котором «Дух Божий живёт» ([[1 Кор 3:16]]). Решения апостольского собора выражены словами: «угодно Святому Духу и нам» ([[Деян 15:28]]) — Дух действует в соборном разуме Церкви.</p>`, s:SRC.dog},
  {q:"Что такое дары Святого Духа?",
   a:`<p>Дары Духа — благодатные способности, подаваемые верующим «на пользу» Церкви ([[1 Кор 12:7]]): различны служения и дарования, но Дух один. Пророк Исаия перечисляет семь даров: премудрости, разума, совета, крепости, ведения, благочестия и страха Божия ([[Ис 11:2]]).</p>
   <p>Дары даются не для превозношения, а для служения и созидания Церкви. Высший путь, без которого все дары ничто, — любовь ([[1 Кор 13:1]]).</p>`, s:SRC.dog},
  {q:"Что такое плоды Духа?",
   a:`<p>Плоды Духа — это черты и свойства обновлённой Им жизни, признаки Его действия в человеке. Апостол называет их: «любовь, радость, мир, долготерпение, благость, милосердие, вера, кротость, воздержание» ([[Гал 5:22]]).</p>
   <p>В отличие от даров, которые различны у разных людей, плоды Духа призваны возрастать в каждом христианине. По ним, а не по внешним знамениям, вернее всего узнаётся подлинное действие Духа.</p>`, s:SRC.pis},
  {q:"Когда христианин получает дар Святого Духа?",
   a:`<p>Печать дара Духа Святого подаётся каждому верующему в таинстве миропомазания, совершаемом сразу по крещении. В апостольское время Дух низводился через возложение рук ([[Деян 8:17]]); ныне это совершается помазанием освящённым миром.</p>
   <p>С этого дара начинается личная духовная жизнь христианина, а возгревать его и приносить плоды человек призван всю жизнь: «духа не угашайте» ([[1 Фес 5:19]]); «дар Божий возгревай» ([[2 Тим 1:6]]).</p>`, s:SRC.dog},
  {q:"Чем отличается действие Духа от ложных «духовных» состояний?",
   a:`<p>Не всякое яркое переживание или «духовный» опыт — от Бога; апостол велит «испытывать духов, от Бога ли они» ([[1 Ин 4:1]]). Действие Святого Духа узнаётся по согласию с верой Церкви, по смирению, миру и любви, которые оно рождает.</p>
   <p>Ложная духовность обычно сопровождается гордостью, превозношением, смущением, разделением. Плоды же Духа — «любовь, радость, мир» ([[Гал 5:22]]); там, где вместо них тщеславие и мятеж, действует не Дух Божий. Верное различение подаётся смирением и советом опытных в вере.</p>`, s:SRC.dog}
 ]
},

/* ============================ 11. ЭККЛЕЗИОЛОГИЯ ============================ */
{
 id:"ekklesiologiya", title:"Учение о Церкви",
 sub:"Экклезиология: природа, признаки, устройство Церкви",
 qa:[
  {q:"Что такое Церковь?",
   a:`<p>Церковь — это установленное Богом общество верующих, соединённых единой православной верой, законным священноначалием и таинствами, глава которого — Сам Христос. Это не просто организация, а живой богочеловеческий организм, Тело Христово.</p>
   <p>«Вы — тело Христово, а порознь — члены» ([[1 Кор 12:27]]), — пишет апостол; Христос же — Глава ([[Еф 1:22]]), а Дух Святой — душа, оживляющая это Тело. Церковь одновременно небесна и земна, включает и живущих на земле, и святых на небесах.</p>`, s:SRC.sim},
  {q:"Кто основал Церковь?",
   a:`<p>Церковь основал Сам Господь Иисус Христос: «создам Церковь Мою, и врата ада не одолеют её» ([[Мф 16:18]]). Он приготовил её всей Своей проповедью, приобрёл Своею Кровью ([[Деян 20:28]]) и оживотворил сошествием Святого Духа в Пятидесятницу.</p>
   <p>Поэтому Церковь не человеческое учреждение, которое можно «переустроить» по своему разумению, а Божие создание. Она пребудет до конца века, ибо утверждена на непоколебимом основании — на Христе.</p>`, s:SRC.sim},
  {q:"Каковы признаки истинной Церкви?",
   a:`<p>Символ веры называет четыре признака: Церковь <em>едина, свята, соборна (кафолична) и апостольна</em>. Эти свойства принадлежат истинной Церкви Христовой и служат мерилом её узнавания.</p>
   <p>Единство её — от единого Главы и единого Духа: «одно тело и один дух… один Господь, одна вера, одно крещение» ([[Еф 4:4]]). Остальные три признака раскрываются далее.</p>`, s:SRC.dog},
  {q:"Почему Церковь едина?",
   a:`<p>Церковь едина, потому что един её Глава — Христос, един оживляющий её Дух, едина вера и едины таинства. Множество поместных Церквей и множество верующих не нарушают единства, как множество членов не разделяет единого тела.</p>
   <p>Господь молился о верующих: «да будут все едино, как Ты, Отче, во Мне, и Я в Тебе» ([[Ин 17:21]]). Поэтому расколы и разделения противны самой природе Церкви, и апостол умоляет «сохранять единство духа в союзе мира» ([[Еф 4:3]]).</p>`, s:SRC.sim},
  {q:"Почему Церковь свята, если в ней есть грешники?",
   a:`<p>Церковь свята не безгрешностью всех своих членов, а святостью своего Главы — Христа, святостью Духа, живущего в ней, святостью её учения и таинств, освящающих людей. Христос «предал Себя за неё, чтобы освятить её… чтобы она была свята и непорочна» ([[Еф 5:25]]).</p>
   <p>Присутствие в Церкви грешников не отменяет её святости: она — не собрание уже совершенных, а врачебница, исцеляющая кающихся. Господь уподобил Церковь полю, где до жатвы растут вместе пшеница и плевелы ([[Мф 13:30]]). Грешники призваны в ней к покаянию и освящению.</p>`, s:SRC.dog},
  {q:"Что значит «соборная» (кафолическая) Церковь?",
   a:`<p>Соборность, или кафоличность (от греч. «по всему», «согласно целому»), означает полноту и всеобщность Церкви: она не привязана к одному народу, месту или времени, объемлет верующих всех стран и эпох и хранит всю полноту истины и благодати.</p>
   <p>Церковь послана научить и крестить «все народы» ([[Мф 28:19]]). Соборность проявляется и в способе жизни и решений — не по воле одного лица, а в согласии всей Церкви, выражаемом особенно на соборах.</p>`, s:SRC.sim},
  {q:"Что значит «апостольская» Церковь?",
   a:`<p>Церковь апостольская в двойном смысле: она хранит неповреждённой веру, преданную апостолами, и сохраняет непрерывное преемство служения, идущее от апостолов через рукоположение епископов.</p>
   <p>Она «утверждена на основании апостолов и пророков, имея Самого Иисуса Христа краеугольным камнем» ([[Еф 2:20]]). Апостольство — залог подлинности: истинна та Церковь, которая учит тому же, чему учили апостолы, и происходит от них.</p>`, s:SRC.dog},
  {q:"Что такое апостольское преемство?",
   a:`<p>Апостольское преемство — это непрерывная передача благодати священства и полномочий учить и совершать таинства от апостолов к их преемникам-епископам через рукоположение, из рода в род до наших дней.</p>
   <p>Апостолы поставляли епископов и пресвитеров ([[Деян 14:23]]) и велели им поставлять других: «что слышал от меня… передай верным людям, которые были бы способны и других научить» ([[2 Тим 2:2]]). Священномученик Ириней Лионский видел в этом преемстве надёжный признак истинной Церкви против еретиков.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Зачем в Церкви иерархия?",
   a:`<p>Церковная иерархия установлена Самим Христом, избравшим апостолов и давшим им власть учить, священнодействовать и пасти. Через них служение передаётся дальше; это не «начальствование» ради власти, а служение ради спасения других.</p>
   <p>«Дух Святый поставил вас блюстителями, пасти Церковь Господа и Бога» ([[Деян 20:28]]). Иерархия хранит единство, чистоту веры и порядок в Церкви. Существуют три степени священства — епископ, пресвитер и диакон.</p>`, s:SRC.dog},
  {q:"Чем различаются епископ, пресвитер и диакон?",
   a:`<p><em>Епископ</em> — высшая степень священства, имеющая всю его полноту, включая право рукополагать других и управлять поместной Церковью. <em>Пресвитер</em> (священник) совершает все таинства, кроме рукоположения, но в подчинении епископу и по его благословению.</p>
   <p><em>Диакон</em> служит при богослужении и таинствах, помогает епископу и пресвитеру, но сам таинств не совершает. Это трёхстепенное устройство восходит к апостольскому веку и хранится в Церкви неизменно.</p>`, s:SRC.dog},
  {q:"Как решаются спорные вопросы в Церкви?",
   a:`<p>Важнейшие вопросы веры и церковного порядка решаются соборно — не властью одного лица, а согласием епископов, выражающим разум всей Церкви. Образец дан ещё апостолами на Иерусалимском соборе, определение которого начиналось словами: «угодно Святому Духу и нам» ([[Деян 15:28]]).</p>
   <p>Высший авторитет в вопросах вероучения принадлежит Вселенским соборам. Соборность — не парламентское большинство, а совместное искание и исповедание истины, открываемой Духом Святым Церкви.</p>`, s:SRC.ist},
  {q:"Что такое Вселенские соборы?",
   a:`<p>Вселенские соборы — собрания епископов всей Церкви (или их представителей) для решения важнейших вопросов веры и осуждения ересей. Их определения (догматы и каноны) Церковь принимает как выражение своей веры, руководимой Духом Святым.</p>
   <p>Православная Церковь признаёт семь Вселенских соборов (325–787 гг.), которые сформулировали учение о Троице, о двух природах Христа и о почитании икон. Их вероучительные определения непогрешимы и неизменны.</p>`, s:SRC.ist},
  {q:"Как относиться к Священному Преданию?",
   a:`<p>Священное Предание — это живая передача веры в Церкви от апостолов доныне: оно включает Писание, вероопределения соборов, творения отцов, богослужение, каноны, иконы — всё, чем Дух Святой хранит и раскрывает истину. Предание и Писание неразделимы: Писание есть записанная часть Предания.</p>
   <p>Апостол велит: «стойте и держите предания, которым вы научены или словом, или посланием нашим» ([[2 Фес 2:15]]). Предание — не «добавка» к Писанию, а тот церковный контекст, в котором Писание верно понимается.</p>`, s:SRC.dog},
  {q:"Что такое поместная и Вселенская Церковь?",
   a:`<p>Вселенская (Кафолическая) Церковь — единая Церковь Христова во всех местах и временах. Поместные Церкви — её части в отдельных странах и народах, соединённые единством веры, таинств и канонического общения при равночестии своих епископов.</p>
   <p>Каждая поместная Церковь, возглавляемая епископом и собранная вокруг Евхаристии, есть не «часть» в смысле дробления, а полнота Церкви на данном месте. Полнота Церкви пребывает в каждой православной общине, объединённой со всеми в единой вере.</p>`, s:SRC.sim},
  {q:"Что произошло в 1054 году?",
   a:`<p>1054 год — символический рубеж «Великого раскола», разделения христианского мира на Западную (Римско-Католическую) и Восточную (Православную) Церкви. В этом году папские легаты и Константинопольский патриарх обменялись взаимными отлучениями.</p>
   <p>Разделение готовилось веками: накапливались различия обрядовые, канонические и вероучительные (прибавка filioque к Символу, притязания Римского епископа на власть над всей Церковью, споры об опресноках и др.). 1054 год лишь обозначил разрыв, который в последующие века стал окончательным.</p>`, s:SRC.ist}
 ]
},

/* ============================ 12. САКРАМЕНТОЛОГИЯ ============================ */
{
 id:"sakramentologiya", title:"Учение о таинствах",
 sub:"Сакраментология: семь таинств Церкви",
 qa:[
  {q:"Что такое таинство?",
   a:`<p>Таинство — это священное действие Церкви, в котором под видимым знаком верующему подаётся невидимая спасительная благодать Святого Духа. В таинстве соединяются видимое (вещество, слова, обряд) и невидимое (действие благодати).</p>
   <p>Таинства установлены Самим Богом, а не выдуманы людьми, и совершаются в Церкви законным священством. Они — не просто символы, а действительные проводники благодати, освящающей всю жизнь человека от рождения до смерти.</p>`, s:SRC.dog},
  {q:"Сколько таинств в Церкви?",
   a:`<p>Церковь издревле совершала многие священнодействия, но собственно таинствами почитает семь: крещение, миропомазание, евхаристию (причащение), покаяние, священство, брак и елеосвящение. Число семь окончательно закрепилось в церковном сознании.</p>
   <p>Каждое таинство подаёт особую благодать на определённом рубеже духовной жизни: рождение (крещение), укрепление (миропомазание), питание (евхаристия), исцеление от грехов (покаяние) и от болезней (елеосвящение), освящение служения (священство) и семьи (брак).</p>`, s:SRC.dog},
  {q:"Что подаётся в крещении?",
   a:`<p>В крещении человек духовно рождается в новую жизнь, очищается от всех прежних грехов (в том числе от первородного повреждения) и вводится в Церковь как член Тела Христова. Троекратное погружение в воду знаменует смерть для греха и совоскресение со Христом ([[Рим 6:4]]).</p>
   <p>Сам Господь установил его необходимость: «если кто не родится от воды и Духа, не может войти в Царствие Божие» ([[Ин 3:5]]). Крещёный «во Христа облекается» ([[Гал 3:27]]). Таинство совершается единожды и неповторимо.</p>`, s:SRC.dog},
  {q:"Почему крестят младенцев?",
   a:`<p>Младенцев крестят по вере родителей и восприемников (крёстных), которые обязуются воспитать их в вере. Как дети наследуют повреждённую природу, так и им нужно духовное возрождение и вхождение в Церковь; лишать их благодати до «сознательного возраста» нет основания.</p>
   <p>Господь звал детей к Себе: «пустите детей приходить ко Мне… ибо таковых есть Царствие Божие» ([[Мк 10:14]]). Апостолы крестили целые «дома́» ([[Деян 16:15]]), куда, по обычаю, входили и дети. Древняя Церковь всегда крестила младенцев.</p>`, s:SRC.dog},
  {q:"Заменило ли крещение ветхозаветное обрезание?",
   a:`<p>Да, для христиан крещение заступило место ветхозаветного обрезания как знак вступления в завет с Богом. Апостол прямо называет его «обрезанием нерукотворенным» — «обрезанием Христовым» ([[Кол 2:11]]), совершаемым не над плотью, а над сердцем.</p>
   <p>Как обрезание вводило в ветхий завет и народ Божий, так крещение вводит в новый завет и в Церковь, но подаёт неизмеримо больше — очищение и благодать возрождения.</p>`, s:SRC.dog},
  {q:"Что подаётся в миропомазании?",
   a:`<p>В миропомазании новокрещёному подаётся печать дара Святого Духа для укрепления и возрастания в новой жизни. Если в крещении человек рождается, то в миропомазании получает силы Духа для духовной жизни, как бы «духовное совершеннолетие».</p>
   <p>В апостольское время Дух низводился через возложение рук ([[Деян 8:17]]); поскольку апостолы не могли лично возлагать руки на всех, установилось помазание освящённым миром, которое совершает священник. «Помазавший нас есть Бог, Который и запечатлел нас» ([[2 Кор 1:21]]).</p>`, s:SRC.dog},
  {q:"Что такое Евхаристия?",
   a:`<p>Евхаристия (греч. «благодарение»), или Причащение, — важнейшее таинство, в котором хлеб и вино действием Святого Духа прелагаются в истинные Тело и Кровь Христовы, и верующие причащаются их во оставление грехов и в жизнь вечную.</p>
   <p>Господь установил его на Тайной вечере, подав хлеб: «сие есть Тело Моё», и чашу: «сие есть Кровь Моя нового завета» ([[Мф 26:26]]), и заповедал: «сие творите в Моё воспоминание» ([[Лк 22:19]]). Евхаристия — средоточие всей жизни Церкви.</p>`, s:SRC.dog},
  {q:"Евхаристия — это только воспоминание Тайной вечери?",
   a:`<p>Нет. Это не просто обряд в память о прошлом и не символ, а действительное приобщение истинных Тела и Крови Христовых. Господь говорил об этом прямо и настойчиво, несмотря на соблазн слушателей: «ядущий Мою Плоть и пиющий Мою Кровь имеет жизнь вечную» ([[Ин 6:54]]).</p>
   <p>Вместе с тем Евхаристия есть и воспоминание («сие творите в Моё воспоминание»), и благодарение, и бескровная жертва, в которой приносится и приобщается единая Жертва Христова. Воспоминание здесь — не мысль о прошлом, а таинственное соучастие в спасительном событии.</p>`, s:SRC.dog},
  {q:"Зачем нужно причащаться?",
   a:`<p>Причащение теснейшим образом соединяет человека со Христом, питает и укрепляет его духовно, очищает грехи, подаёт залог вечной жизни и соединяет верующих между собою в одно Тело. «Пребывающий во Мне, и Я в нём, тот приносит много плода» ([[Ин 15:5]]); «Хлеб один, и мы многие одно тело» ([[1 Кор 10:17]]).</p>
   <p>Без причащения духовная жизнь оскудевает: «если не будете есть Плоти Сына Человеческого… не будете иметь в себе жизни» ([[Ин 6:53]]). Приступать к нему должно с верой, покаянием, примирением и рассуждением, «испытывая себя» ([[1 Кор 11:28]]).</p>`, s:SRC.dog},
  {q:"Что такое таинство покаяния?",
   a:`<p>Покаяние — таинство исцеления, в котором крещёный, искренне исповедуя свои грехи перед Богом при священнике, получает от Бога прощение и разрешение. Священник — не судья и не «посредник», отбирающий власть у Бога, а свидетель и служитель, которому Христос дал власть разрешать.</p>
   <p>Господь дал апостолам эту власть: «кому простите грехи, тому простятся; на ком оставите, на том останутся» ([[Ин 20:23]]). Покаяние возвращает человеку утраченную в грехах благодать крещения, потому его называют «вторым крещением».</p>`, s:SRC.dog},
  {q:"Что нужно для истинного покаяния?",
   a:`<p>Для истинного покаяния нужны: осознание и искреннее сокрушение о грехах, откровенное их исповедание без самооправдания, твёрдая решимость исправиться и оставить грех, а также вера в милосердие Божие и надежда на прощение.</p>
   <p>Покаяние (греч. «метанойя») означает не просто сожаление, а <em>перемену ума</em> и жизни: «сотворите же достойный плод покаяния» ([[Мф 3:8]]). Без намерения исправиться исповедь остаётся бесплодной. Господь принимает всякого кающегося, как отец — блудного сына ([[Лк 15:20]]).</p>`, s:SRC.dog},
  {q:"Что такое таинство священства?",
   a:`<p>Священство (рукоположение, хиротония) — таинство, в котором через молитву и возложение рук епископа правильно избранному подаётся благодать Святого Духа для совершения таинств, учительства и пастырского служения в соответствующей степени.</p>
   <p>Апостолы поставляли служителей возложением рук ([[Деян 6:6]]); апостол напоминает Тимофею о «даровании, которое дано тебе… с возложением рук священства» ([[1 Тим 4:14]]). Совершать это таинство может только епископ, имеющий апостольское преемство.</p>`, s:SRC.dog},
  {q:"Почему брак — таинство?",
   a:`<p>Супружеский союз мужа и жены установлен Самим Богом ещё в раю: «оставит человек отца и мать и прилепится к жене своей; и будут двое одна плоть» ([[Быт 2:24]]). В Церкви этот союз освящается благодатью, которая соединяет супругов и помогает им нести общую жизнь в любви и верности.</p>
   <p>Апостол Павел видит в христианском браке образ таинственного союза Христа и Церкви и называет это «тайной великой» ([[Еф 5:32]]). Христос благословил брак Своим присутствием и первым чудом в Кане Галилейской ([[Ин 2:1]]).</p>`, s:SRC.dog},
  {q:"Что такое елеосвящение (соборование)?",
   a:`<p>Елеосвящение — таинство, в котором при помазании больного освящённым елеем и молитве священников подаётся благодать, исцеляющая немощи души и тела и отпускающая забытые и нераскаянные по немощи грехи.</p>
   <p>Оно прямо заповедано апостолом: «болен ли кто из вас, пусть призовёт пресвитеров Церкви, и пусть помолятся над ним, помазав его елеем во имя Господне… и восставит его Господь; и если он соделал грехи, простятся ему» ([[Иак 5:14]]). По числу совершающих его пресвитеров таинство называют также «соборованием».</p>`, s:SRC.dog}
 ]
},

/* ============================ 13. ЛИТУРГИКА И МОЛИТВА ============================ */
{
 id:"liturgika", title:"Богослужение и молитва",
 sub:"Литургика: молитва, праздники, пост",
 qa:[
  {q:"Что такое молитва?",
   a:`<p>Молитва — это живое общение человека с Богом, возношение к Нему ума и сердца. Она бывает славословием (прославлением Бога), благодарением, покаянием и прошением о своих и чужих нуждах.</p>
   <p>Молитва — дыхание духовной жизни; без неё вера охладевает. Господь заповедал «всегда молиться и не унывать» ([[Лк 18:1]]), а апостол — «непрестанно молитесь» ([[1 Фес 5:17]]). Молиться можно словами, установленными Церковью, и своими, вслух и в сердце, в храме и всюду.</p>`, s:SRC.dog},
  {q:"Какая молитва — главная?",
   a:`<p>Главная христианская молитва — «Отче наш», которую дал Сам Господь в ответ на просьбу учеников научить их молиться ([[Мф 6:9]]). Потому её называют молитвой Господней.</p>
   <p>В ней кратко собрано всё главное: прославление имени Божия, желание пришествия Его Царства и исполнения Его воли, прошение о насущном хлебе, о прощении грехов (в меру нашего прощения других) и об избавлении от искушения и зла. Она — образец всякой молитвы.</p>`, s:SRC.pis},
  {q:"Что такое Божественная литургия?",
   a:`<p>Литургия (греч. «общее дело») — главное богослужение Церкви, за которым совершается таинство Евхаристии. В её чинопоследовании воспоминается всё домостроительство спасения — от пророчеств до Второго пришествия, — и приносится бескровная жертва.</p>
   <p>Она совершается во исполнение заповеди Господа: «сие творите в Моё воспоминание» ([[Лк 22:19]]). Литургия — средоточие церковной жизни, где земная Церковь соединяется с небесной в единой хвале. Наиболее употребительны литургии святителей Иоанна Златоуста и Василия Великого.</p>`, s:SRC.dog},
  {q:"Зачем нужны храм и общая молитва?",
   a:`<p>Храм — место особого, благодатного присутствия Божия, дом молитвы и совершения таинств, где Церковь собирается как единое тело. Хотя молиться можно везде, общая молитва в храме имеет особую силу.</p>
   <p>Господь обещал: «где двое или трое собраны во имя Моё, там Я посреди них» ([[Мф 18:20]]). Первые христиане «постоянно пребывали… в преломлении хлеба и в молитвах» ([[Деян 2:42]]). Общая молитва соединяет верующих между собою и учит любви.</p>`, s:SRC.dog},
  {q:"Что такое церковные праздники?",
   a:`<p>Праздники — установленные Церковью дни воспоминания спасительных событий, прославления Бога, Богородицы и святых. Они не просто память о прошлом, а благодатное соучастие в празднуемом событии.</p>
   <p>Главный праздник — Пасха, Воскресение Христово, «праздников праздник и торжество из торжеств». За ней следуют двунадесятые праздники (двенадцать важнейших), посвящённые событиям жизни Спасителя и Божией Матери, и многие памяти святых. Праздники строят церковный год.</p>`, s:SRC.pred},
  {q:"Зачем нужен пост?",
   a:`<p>Пост — это воздержание от определённой пищи и от развлечений и страстей ради того, чтобы облегчить телу молитву, обуздать плоть и очистить душу. Пост телесный без духовного (без молитвы, воздержания от гнева и осуждения) бесплоден.</p>
   <p>Сам Господь постился сорок дней ([[Мф 4:2]]) и учил, что иные искушения побеждаются «только молитвою и постом» ([[Мф 17:21]]). Пост — древнее установление: постились пророки, апостолы, вся ранняя Церковь. Он готовит к великим праздникам и укрепляет волю.</p>`, s:SRC.dog},
  {q:"Что такое воскресный день?",
   a:`<p>Воскресенье — «день Господень» ([[Откр 1:10]]), еженедельная малая Пасха, посвящённая воспоминанию Воскресения Христова. Он пришёл на смену ветхозаветной субботе как день покоя и особого посвящения Богу.</p>
   <p>С апостольских времён христиане собирались именно в первый день недели «для преломления хлеба» — на Евхаристию ([[Деян 20:7]]). В этот день верующие оставляют суетные дела и участвуют в богослужении.</p>`, s:SRC.ist},
  {q:"Что такое крестное знамение?",
   a:`<p>Крестное знамение — молитвенное изображение на себе креста Христова, которым христианин исповедует веру в Святую Троицу (три соединённых перста) и в спасительный Крест, освящает и ограждает себя. Оно сопровождает молитву и вход во всякое дело.</p>
   <p>Крест — сила Божия и знамя победы Христовой; апостол хвалится «только крестом Господа нашего Иисуса Христа» ([[Гал 6:14]]). Древность крестного знамения свидетельствуют уже писатели первых веков.</p>`, s:SRC.pred},
  {q:"Можно ли молиться своими словами?",
   a:`<p>Да. Церковь высоко ценит и установленные молитвы (в них — опыт и слова святых, ограждающие от заблуждений), и молитву своими словами, идущую от сердца. Одно не исключает другого.</p>
   <p>Важнее всего не красота слов, а сокрушение и искренность: Господь предостерёг от «многословия» язычников, думающих быть услышанными за множество слов ([[Мф 6:7]]), и принял краткую молитву мытаря: «Боже, будь милостив ко мне, грешнику» ([[Лк 18:13]]).</p>`, s:SRC.dog}
 ]
},

/* ============================ 14. МАРИОЛОГИЯ И ПОЧИТАНИЕ СВЯТЫХ ============================ */
{
 id:"pochitanie", title:"Богородица, святые и иконы",
 sub:"Мариология и почитание святыни",
 qa:[
  {q:"Почему Деву Марию называют Богородицей?",
   a:`<p>Потому что Она родила по плоти Господа Иисуса Христа, Который есть не «простой человек», а единое Лицо воплотившегося Сына Божия — истинного Бога. Именование относится не к тому, будто Она родила Божество, а к тому, что Рождённый от Неё есть Бог.</p>
   <p>Наименование «Богородица» (греч. <em>Феотокос</em>) утвердил III Вселенский собор (Ефес, 431 г.) против Нестория, отвергавшего его. Ещё праведная Елисавета, исполнившись Духа, назвала Марию «Матерью Господа моего» ([[Лк 1:43]]).</p>`, s:SRC.ist},
  {q:"Почему Богородицу почитают выше всех святых?",
   a:`<p>Как Матерь Божия, послужившая величайшей тайне — воплощению Сына Божия, — Пресвятая Дева превосходит достоинством и близостью к Богу всех святых и самих ангелов. Она — «честнейшая херувим и славнейшая без сравнения серафим».</p>
   <p>Сама Она пророчески изрекла: «отныне будут ублажать Меня все роды» ([[Лк 1:48]]). Это почитание — не поклонение как Богу (что принадлежит одному Богу), а высшее среди тварей ублажение и любовь. Церковь молитвенно прибегает к Её ходатайству.</p>`, s:SRC.pred},
  {q:"Зачем молиться святым, если есть Христос?",
   a:`<p>Молясь святым, мы не ставим их на место Христа и не считаем их «вторыми спасителями». Мы просим их молиться о нас вместе с нами и за нас — так же, как просим молитв у живых людей, у близких по вере.</p>
   <p>Святые живы у Бога, ибо Он «Бог не мёртвых, но живых» ([[Мф 22:32]]), и любовь их к нам не прекратилась. «Много может усиленная молитва праведного» ([[Иак 5:16]]); тем более — молитва прославленных Богом святых. Единый Ходатай-Искупитель — Христос ([[1 Тим 2:5]]), а святые — наши молитвенники пред Ним.</p>`, s:SRC.dog},
  {q:"Кто такие святые?",
   a:`<p>Святые — это люди, которые благодатью Божией и своим подвигом достигли святости, угодили Богу и прославлены Им, в том числе чудесами. Церковь чтит разные лики святости: апостолов, пророков, мучеников, святителей (епископов), преподобных (монахов), праведных, бессребреников.</p>
   <p>Прославление (канонизация) не «делает» человека святым, а свидетельствует о святости, уже явленной Богом. Святые — не безгрешные от природы, а те, кто прошёл путём покаяния и любви; их пример и молитвы укрепляют верующих ([[Евр 12:1]]).</p>`, s:SRC.ist},
  {q:"Кто такие мученики?",
   a:`<p>Мученики (греч. «свидетели») — христиане, претерпевшие страдания и смерть за веру во Христа, не отрёкшись от Него. Их подвиг — высшее свидетельство любви ко Христу, уподобление Его крестной смерти.</p>
   <p>В первые три века гонений их были тысячи; кровь мучеников, по известному слову Тертуллиана, стала семенем христиан — гонения не истребили, а умножили Церковь. Господь обещал им: «Будь верен до смерти, и дам тебе венец жизни» ([[Откр 2:10]]).</p>`, s:SRC.ist},
  {q:"Не идолопоклонство ли — почитание икон?",
   a:`<p>Нет. Идолопоклонство — это поклонение ложным богам и обожествление твари. Икона же не бог и не изображение ложного божества, а образ, возводящий ум к Первообразу — ко Христу, Богородице, святым. По слову святых отцов, «честь, воздаваемая образу, восходит к первообразу».</p>
   <p>Поклоняются не доске и краскам, а изображённому. Иконопочитание утвердил VII Вселенский собор (787 г.), различив <em>поклонение-служение</em> (латрию), подобающее одному Богу, и <em>почитательное поклонение</em>, воздаваемое иконам и святым. Иконоборчество было осуждено как ересь.</p>`, s:SRC.ist},
  {q:"Почему можно изображать Христа?",
   a:`<p>Потому что Сын Божий стал истинным человеком, был видим и осязаем: «о том, что мы слышали, что видели своими очами, что рассматривали и что осязали руки наши, — о Слове жизни» ([[1 Ин 1:1]]). Невидимого Бога изобразить нельзя, но воплотившегося и ставшего видимым — можно.</p>
   <p>Поэтому икона Христа — исповедание реальности воплощения. Иконоборцы, отвергая образ, по сути умаляли и самое воплощение. Возможность изображать Христа коренится в том, что «Слово стало плотию» ([[Ин 1:14]]).</p>`, s:SRC.ist},
  {q:"Зачем почитают мощи и святыни?",
   a:`<p>Тела святых при жизни были храмами Святого Духа ([[1 Кор 6:19]]) и приобщились благодати; эта освящённость не исчезает и по смерти, потому мощи чтутся и нередко подают исцеления. Почитается не «прах» сам по себе, а действующая через святых благодать Божия.</p>
   <p>Уже в Ветхом Завете от костей пророка Елисея ожил умерший ([[4 Цар 13:21]]), а в Новом от платков апостола Павла подавались исцеления ([[Деян 19:12]]). Церковь издревле чтила гробницы мучеников и совершала на их мощах Евхаристию.</p>`, s:SRC.ist}
 ]
},

/* ============================ 15. ЭСХАТОЛОГИЯ ============================ */
{
 id:"eshatologiya", title:"Последние времена",
 sub:"Эсхатология: смерть, суд, вечная жизнь",
 qa:[
  {q:"Что бывает с душой после смерти?",
   a:`<p>Смерть — это разлучение души с телом; сама душа не умирает и не «засыпает», но продолжает жить, сознавать и помнить. По смерти она проходит частный суд, определяющий её предначальное состояние — предвкушение блаженства или мучения — в ожидании всеобщего воскресения.</p>
   <p>Это состояние ещё не окончательно: полнота воздаяния наступит после всеобщего суда, когда с душою воссоединится воскресшее тело. Господь есть «Бог живых» ([[Мф 22:32]]), и для верующего смерть — не уничтожение, а переход.</p>`, s:SRC.dog},
  {q:"Что такое частный суд?",
   a:`<p>Частный суд — это определение участи каждой души сразу по её разлучении с телом, до всеобщего суда. «Человекам положено однажды умереть, а потом суд» ([[Евр 9:27]]).</p>
   <p>По этому суду праведные вводятся в предвкушение блаженства (как разбойник, которому обещан рай — [[Лк 23:43]]), а нераскаянные грешники — в ожидание мучения (как в притче о богаче и Лазаре — [[Лк 16:23]]). Окончательный приговор произнесётся на Страшном суде.</p>`, s:SRC.dog},
  {q:"Полезны ли молитвы об умерших?",
   a:`<p>Да. Поскольку до всеобщего суда участь души не является окончательной, молитва Церкви, милостыня и особенно поминовение на Евхаристии могут облегчить состояние усопших и испросить им милость Божию — если только они не умерли в ожесточённом отвержении Бога.</p>
   <p>Уже в Ветхом Завете приносили жертву за умерших, «да разрешатся от греха» (2 Мак. 12:44); христианская Церковь с древности молится о своих усопших. Эта молитва — выражение любви, которая «не перестаёт» ([[1 Кор 13:8]]) и за гробом.</p>`, s:SRC.dog},
  {q:"Что такое всеобщее воскресение?",
   a:`<p>В конце времён, при Втором пришествии Христа, все умершие воскреснут телесно — душа каждого вновь соединится с воскрешённым телом. «Наступает время, в которое все, находящиеся в гробах, услышат глас Сына Божия и изыдут» ([[Ин 5:28]]).</p>
   <p>Воскресшее тело будет иным — нетленным, бессмертным, духовным, но тем же самым телом человека: «сеется в тлении, восстаёт в нетлении» ([[1 Кор 15:42]]). Образ и залог нашего воскресения — воскресшее тело Христово.</p>`, s:SRC.dog},
  {q:"Что такое Страшный суд?",
   a:`<p>Страшный (последний, всеобщий) суд — суд Христов над всем родом человеческим при Его Втором пришествии, когда откроются дела, слова и помышления каждого и определится вечная участь всех.</p>
   <p>Господь изобразил его в притче: «соберутся пред Ним все народы; и отделит одних от других, как пастырь отделяет овец от козлов» ([[Мф 25:32]]), — и мерилом суда будут дела любви и милосердия. Суд праведен, ибо совершается Всеведущим и Всеблагим.</p>`, s:SRC.dog},
  {q:"Что такое антихрист?",
   a:`<p>Антихрист — противник Христа, который, по пророчеству, явится перед концом мира, обольстит многих ложными знамениями и воздвигнет гонение на верных ([[2 Фес 2:3|2 Фес 2:3-4]]). Само имя означает и «против Христа», и «вместо Христа».</p>
   <p>Его царство будет кратким, и пришествие Господне упразднит его «духом уст Своих» ([[2 Фес 2:8]]). Апостол предупреждал, что «дух антихриста» действует в мире уже и что «есть много антихристов» ([[1 Ин 4:3]]) — всех, кто противится Христу.</p>`, s:SRC.dog},
  {q:"Что такое вечная жизнь?",
   a:`<p>Вечная жизнь — не просто бесконечное существование, а совершенное общение с Богом, полнота блаженства в любви и созерцании Его. Господь определил её так: «Сия же есть жизнь вечная, да знают Тебя, единого истинного Бога, и посланного Тобою Иисуса Христа» ([[Ин 17:3]]).</p>
   <p>В ней прекратятся смерть, болезнь и скорбь; праведные увидят Бога «лицем к лицу» ([[1 Кор 13:12]]) и уподобятся Ему ([[1 Ин 3:2]]). Это блаженство превосходит всякое воображение: «не видел того глаз… что приготовил Бог любящим Его» ([[1 Кор 2:9]]).</p>`, s:SRC.dog},
  {q:"Что такое вечная мука и совместима ли она с любовью Божией?",
   a:`<p>Итог суда двойствен: «И пойдут сии в муку вечную, а праведники в жизнь вечную» ([[Мф 25:46]]). Мука — это состояние отпадения от Бога, добровольного пребывания вне Его любви и света, которое человек сам избрал и в котором ожесточился.</p>
   <p>Бог никого не творит для погибели и «хочет, чтобы все… спаслись» ([[1 Тим 2:4]]). Но любовь не насилует: она не может принудить к общению того, кто до конца его отверг. Мука — не «месть» Бога, а последствие свободного и окончательного отвержения Источника жизни.</p>`, s:SRC.dog},
  {q:"Одинаково ли блаженство всех праведных?",
   a:`<p>Нет. Блаженство едино по существу (все — в общении с Богом), но различно по мере, по степени восприятия благодати, соответственно духовному состоянию каждого. Бог воздаёт по правде, и всякий вмещает столько, сколько может.</p>
   <p>«В доме Отца Моего обителей много» ([[Ин 14:2]]); «иная слава солнца, иная слава луны… звезда от звезды разнится в славе. Так и при воскресении мёртвых» ([[1 Кор 15:41]]). При этом никто не будет завидовать: каждый исполнен блаженства по своей мере.</p>`, s:SRC.dog},
  {q:"Что будет с миром в конце?",
   a:`<p>Мир не будет уничтожен, но преображён и обновлён, освобождён от тления и зла. «Увидел я новое небо и новую землю» ([[Откр 21:1]]); прежнее прейдёт, но само творение «освобождено будет от рабства тлению» ([[Рим 8:21]]).</p>
   <p>Тогда Бог «отрёт всякую слезу с очей их, и смерти не будет уже» ([[Откр 21:4]]), и настанет полнота Царства, где «будет Бог всё во всём» ([[1 Кор 15:28]]). К этому обновлению устремлена вся история спасения.</p>`, s:SRC.dog}
 ]
},

/* ============================ 16. ПАТРОЛОГИЯ И ИСТОРИЯ ЦЕРКВИ ============================ */
{
 id:"istoriya", title:"Отцы и история Церкви",
 sub:"Патрология и церковная история",
 qa:[
  {q:"Кто такие отцы Церкви?",
   a:`<p>Отцы Церкви — святые учители древности, засвидетельствовавшие и изложившие веру Церкви, к которым Церковь относится с особым авторитетом. Отца Церкви отличают правость учения (православие), святость жизни, признание Церковью и древность.</p>
   <p>Их согласное свидетельство — «согласие отцов» (лат. <em>consensus patrum</em>) — важная часть Предания и надёжное мерило веры. Среди величайших — святители Афанасий Великий, Василий Великий, Григорий Богослов, Иоанн Златоуст, на Западе — блаженный Августин.</p>`, s:SRC.ist},
  {q:"Что такое патрология?",
   a:`<p>Патрология — раздел богословской науки, изучающий жизнь, творения и учение отцов и церковных писателей. Она показывает, как Церковь в разные эпохи раскрывала, формулировала и защищала свою веру.</p>
   <p>Патрология помогает понимать догматы в их историческом развитии — не как «изобретения», а как всё более точные выражения одной и той же апостольской веры, отчеканенные часто в борьбе с ересями.</p>`, s:SRC.sim},
  {q:"Кто написал первую историю Церкви?",
   a:`<p>Отцом церковной истории считается Евсевий, епископ Кесарии Палестинской (около 260–340 гг.). Его «Церковная история» в десяти книгах охватывает время от апостолов до эпохи Константина Великого.</p>
   <p>Ценность его труда особенно в том, что он обильно приводит выдержки из древних документов и сочинений, многие из которых иначе были бы утрачены. Благодаря Евсевию мы знаем множество свидетельств о ранней Церкви, мучениках и епископских преемствах.</p>`, s:SRC.ist},
  {q:"Как начиналась Церковь?",
   a:`<p>Церковь родилась в Иерусалиме в день Пятидесятницы, когда на апостолов сошёл Святой Дух и апостол Пётр обратил своей проповедью около трёх тысяч человек ([[Деян 2:41]]). Первая община жила в единодушии, молитве, учении апостолов и преломлении хлеба.</p>
   <p>Из Иерусалима, а затем через проповедь апостолов (особенно Павла) вера распространилась по городам Римской империи — среди иудеев и язычников. Так исполнялось повеление Христа быть Ему свидетелями «даже до края земли» ([[Деян 1:8]]).</p>`, s:SRC.ist},
  {q:"Как и почему гнали первых христиан?",
   a:`<p>Сначала христиан преследовали иудейские власти (первомученик Стефан, апостол Иаков). Затем на протяжении почти трёх веков Церковь терпела гонения от Римской империи. Причины были и религиозные, и государственные: христиане отказывались приносить жертвы языческим богам и обожествлённому императору, что считалось преступлением против государства.</p>
   <p>Гонения то вспыхивали, то затихали, при разных императорах (Нероне, Деции, Диоклетиане и др.). Несмотря на казни, вера не ослабевала, а росла — мужество мучеников привлекало новых верующих.</p>`, s:SRC.ist},
  {q:"Что изменил Константин Великий?",
   a:`<p>При императоре Константине Великом положение Церкви коренным образом изменилось: Миланским эдиктом (313 г.) христианство получило свободу, гонения прекратились, Церковь перешла от преследований к союзу с государством.</p>
   <p>Константин созвал и Первый Вселенский собор в Никее (325 г.), открыв эпоху Вселенских соборов. Его царствование стало рубежом между эпохой гонимой Церкви катакомб и эпохой Церкви, свободно устрояющей свою жизнь и вероучение.</p>`, s:SRC.ist},
  {q:"Где и когда принят Символ веры?",
   a:`<p>Основу Символа веры составили отцы Первого Вселенского собора в Никее (325 г.), оградив словом «единосущный» веру в истинное Божество Сына против Ария. Второй Вселенский собор (Константинополь, 381 г.) дополнил его, раскрыв учение о Святом Духе.</p>
   <p>Поэтому Символ называется Никео-Цареградским. Он содержит краткое исповедание всей христианской веры — о Троице, о Христе, о Церкви, о крещении и вечной жизни — и с тех пор остаётся неизменным.</p>`, s:SRC.ist},
  {q:"Сколько было Вселенских соборов и против чего они?",
   a:`<p>Церковь признаёт семь Вселенских соборов. <em>Первый</em> (Никея, 325) — против Ария, утвердил Божество Сына. <em>Второй</em> (Константинополь, 381) — против духоборцев, о Божестве Духа. <em>Третий</em> (Ефес, 431) — против Нестория, о единстве Лица Христа и о Богородице. <em>Четвёртый</em> (Халкидон, 451) — против монофизитства, о двух природах.</p>
   <p><em>Пятый</em> (553) — по поводу споров, связанных с несторианством и оригенизмом. <em>Шестой</em> (680–681) — против монофелитства, о двух волях Христа. <em>Седьмой</em> (Никея, 787) — против иконоборчества, утвердил иконопочитание. Так соборно раскрывалось учение о Троице и о Христе.</p>`, s:SRC.ist},
  {q:"Кто такой святитель Афанасий Великий?",
   a:`<p>Святитель Афанасий (около 296–373), архиепископ Александрийский, — главный защитник православия в арианских спорах IV века. Ещё диаконом он участвовал в Никейском соборе, а затем всю жизнь отстаивал единосущие Сына, за что пять раз был изгоняем со своей кафедры.</p>
   <p>Его называют «отцом православия»; известны его слова о цели воплощения: Сын Божий стал человеком, чтобы человека сделать богом по благодати. Его стойкость («Афанасий против всего мира») сохранила Церкви никейскую веру.</p>`, s:SRC.ist},
  {q:"Что такое ереси и как Церковь на них отвечала?",
   a:`<p>Ересь — это упорное искажение какого-либо догмата веры, отделяющее человека от Церкви. В первые века Церковь встретила множество ересей: гностицизм, арианство, несторианство, монофизитство, иконоборчество и другие.</p>
   <p>Отвечала Церковь на них соборно — определениями Вселенских соборов и трудами отцов, точно выражая веру там, где еретики её искажали. Как заметил блаженный Августин, многое в вероучении раскрылось яснее именно тогда, когда истину пришлось защищать. Так ереси невольно послужили более точному исповеданию веры.</p>`, s:SRC.dog},
  {q:"Как распространялось христианство у славян?",
   a:`<p>В IX веке святые равноапостольные братья Кирилл и Мефодий, просветители славян, создали славянскую азбуку и перевели на славянский язык Писание и богослужение. Это открыло славянским народам путь к вере на родном языке.</p>
   <p>Христианство приняли болгары, сербы, моравы, а в 988 году — Русь при князе Владимире. Так славянские народы вошли в семью христианских Церквей и восприняли византийскую православную традицию.</p>`, s:SRC.ist},
  {q:"В чём причины разделения Церквей 1054 года?",
   a:`<p>Причины «Великого раскола» копились веками и были разнородны. Вероучительная — внесение Западом в Символ веры прибавки filioque (об исхождении Духа «и от Сына»). Каноническая — растущие притязания Римского епископа на единоличную власть над всей Церковью, тогда как Восток признавал равночестие патриархов и первенство чести Рима лишь как «первого среди равных».</p>
   <p>Добавлялись обрядовые различия (опресноки, посты) и культурно-политическое отдаление Запада и Востока. Формальным рубежом стали взаимные отлучения 1054 года, а окончательным разрыв сделали позднейшие события. Так единая до тех пор Церковь разделилась на Православную и Римско-Католическую.</p>`, s:SRC.ist}
 ]
},

/* ============================ 17. ХРИСТИАНСКАЯ ЭТИКА ============================ */
{
 id:"etika", title:"Христианская жизнь",
 sub:"Нравственное богословие: заповеди и добродетели",
 qa:[
  {q:"В чём главная заповедь христианина?",
   a:`<p>Главная заповедь — о любви к Богу и к ближнему. На вопрос о наибольшей заповеди Господь ответил: «Возлюби Господа Бога твоего всем сердцем твоим… это первая и наибольшая заповедь; вторая же подобная ей: возлюби ближнего твоего, как самого себя» ([[Мф 22:37]]).</p>
   <p>На этих двух заповедях «утверждается весь закон и пророки». Любовь — исполнение всего закона ([[Рим 13:10]]) и то, по чему узнаются ученики Христовы: «по тому узнают все, что вы Мои ученики, если будете иметь любовь между собою» ([[Ин 13:35]]).</p>`, s:SRC.pis},
  {q:"Каковы главные христианские добродетели?",
   a:`<p>Высшие, «богословские» добродетели — вера, надежда и любовь, из которых «любовь больше» ([[1 Кор 13:13]]), ибо она пребывает вечно. Они связуют человека непосредственно с Богом.</p>
   <p>К ним примыкают «естественные» добродетели — рассудительность, мужество, воздержание и справедливость. Все истинные добродетели — плод действия благодати в свободном человеке; без любви даже великие дела «ничто» ([[1 Кор 13:2]]).</p>`, s:SRC.dog},
  {q:"Что такое Заповеди блаженства?",
   a:`<p>Заповеди блаженства — девять изречений, которыми Христос открыл Нагорную проповедь ([[Мф 5:3]]), указав путь к истинному счастью в Боге. Они рисуют образ христианина: нищета духа (смирение), плач о грехах, кротость, алкание правды, милосердие, чистота сердца, миротворчество, терпение гонений за правду.</p>
   <p>Каждой из них обещано блаженство — не земное благополучие, а близость к Богу и Царство Небесное. Заповеди блаженства не отменяют десять заповедей, а возводят нравственную жизнь к её вершине — уподоблению Христу.</p>`, s:SRC.pis},
  {q:"Как относиться к врагам?",
   a:`<p>По прямой заповеди Христа — с любовью и прощением: «любите врагов ваших, благословляйте проклинающих вас, благотворите ненавидящим вас и молитесь за обижающих вас» ([[Мф 5:44]]). Это одна из самых трудных и самых отличительных черт христианства.</p>
   <p>Любовь к врагам не означает одобрения зла или отказа от справедливости; она означает не воздавать злом за зло, желать обидчику добра и спасения. «Не будь побеждён злом, но побеждай зло добром» ([[Рим 12:21]]). Так человек уподобляется Отцу Небесному, благому и к неблагодарным.</p>`, s:SRC.pis},
  {q:"Что такое смирение и почему оно так важно?",
   a:`<p>Смирение — это правдивое видение себя перед Богом: сознание своей немощи и зависимости от Бога, свобода от гордости, тщеславия и самопревозношения. Оно — не самоуничижение и не слабость, а основание всех добродетелей.</p>
   <p>Христос дал образ смирения и прямо призвал: «научитесь от Меня, ибо Я кроток и смирен сердцем» ([[Мф 11:29]]). «Бог гордым противится, а смиренным даёт благодать» ([[Иак 4:6]]). Гордость низвергла денницу, смирение же возводит человека к Богу.</p>`, s:SRC.dog},
  {q:"Как христианину относиться к богатству?",
   a:`<p>Богатство само по себе не грех; грешно порабощение им сердца, сребролюбие и немилосердие. Опасность в том, что богатство легко становится идолом: «не можете служить Богу и маммоне» ([[Мф 6:24]]).</p>
   <p>От имеющих достаток требуется нестяжательность, благодарность и щедрость. «Корень всех зол есть сребролюбие» ([[1 Тим 6:10]]); истинное сокровище — на небесах, «где ни моль, ни ржа не истребляют» ([[Мф 6:20]]). Богатством должно распоряжаться как доверенным от Бога, служа им ближним.</p>`, s:SRC.pis},
  {q:"Что такое милостыня и дела милосердия?",
   a:`<p>Милостыня — деятельная любовь к нуждающимся, помощь голодному, больному, заключённому, страннику. Это не «необязательное дополнение», а прямое требование веры, по которому будет суд.</p>
   <p>Господь отождествляет Себя с нуждающимися: «так как вы сделали это одному из сих братьев Моих меньших, то сделали Мне» ([[Мф 25:40]]). Дела милосердия — свидетельство живой веры и путь уподобления милосердному Богу; творить их следует не напоказ, а в тайне ([[Мф 6:3]]).</p>`, s:SRC.pis},
  {q:"Как относиться к власти и государству?",
   a:`<p>Христианин повинуется законной власти и исполняет гражданский долг в том, что не противоречит вере: «отдавайте кесарево кесарю, а Божие Богу» ([[Мф 22:21]]). Апостол учит, что «нет власти не от Бога» ([[Рим 13:1]]) — то есть сам порядок власти установлен Богом ради общего блага.</p>
   <p>Однако послушание властям не безусловно: когда власть требует греха или отречения от Бога, действует высший закон — «должно повиноваться больше Богу, нежели человекам» ([[Деян 5:29]]). Так первые христиане чтили императора, но отказывались поклоняться ему как богу.</p>`, s:SRC.pis},
  {q:"В чём смысл страдания в христианской жизни?",
   a:`<p>Страдание вошло в мир через грех и само по себе не благо; но, принятое с верой и терпением, оно очищает душу, смиряет, отрывает от привязанности к земному и соединяет с крестом Христовым. Христос не отменил страдание, а прошёл через него и наполнил смыслом.</p>
   <p>«Нынешние временные страдания ничего не стоят в сравнении с той славою, которая откроется в нас» ([[Рим 8:18]]). Скорби христианин несёт не с отчаянием, а с надеждой, зная, что «любящим Бога… всё содействует ко благу» ([[Рим 8:28]]).</p>`, s:SRC.dog},
  {q:"К чему призван каждый христианин?",
   a:`<p>Каждый христианин, а не только монахи и подвижники, призван к святости и совершенству в любви. Это призвание всеобще: «будьте святы, потому что Я свят» ([[1 Пет 1:16]]); «воля Божия есть освящение ваше» ([[1 Фес 4:3]]).</p>
   <p>Святость достигается не бегством от обычной жизни, а исполнением заповедей на своём месте — в семье, труде, служении, — через веру, участие в таинствах, молитву и дела любви. Путь этот завершается в вечном общении с Богом, для которого человек и сотворён.</p>`, s:SRC.dog}
 ]
},
];
